import CROSSWORDS from "../assets/data/crosswords.json";
import GRID_LOGIC from "../assets/data/grid_logic.json";
import CAMPGROUND_LEVEL from "../assets/data/levels/campground/campground.json";
import CAMPGROUND_BACKGROUND from "../assets/data/levels/campground/campground_background.png";
import CAMPGROUND_FOREGROUND from "../assets/data/levels/campground/campground_foreground.png";
import CAMPGROUND_EVENTS from "../assets/data/levels/campground/events.json";
import CAMPGROUND_NPCS from "../assets/data/levels/campground/npcs.json";
import CAMPGROUND_READABLES from "../assets/data/levels/campground/readables.json";
import SUDOKU from "../assets/data/sudoku.json";
import DEER_JSON from "../assets/images/npcs/campground/deer.json";
import DEER_IMG from "../assets/images/npcs/campground/deer.png";
import DEER_CHOCOLATE_JSON from "../assets/images/npcs/campground/deer_chocolate.json";
import DEER_CHOCOLATE_IMG from "../assets/images/npcs/campground/deer_chocolate.png";
import DEER_GOLD_JSON from "../assets/images/npcs/campground/deer_gold.json";
import DEER_GOLD_IMG from "../assets/images/npcs/campground/deer_gold.png";
import DEER_GREEN_JSON from "../assets/images/npcs/campground/deer_green.json";
import DEER_GREEN_IMG from "../assets/images/npcs/campground/deer_green.png";
import SQUIRREL_JSON from "../assets/images/npcs/campground/squirrel.json";
import SQUIRREL_IMG from "../assets/images/npcs/campground/squirrel.png";
import PAPER_ICON from "../assets/images/ui/paper_icon.png";
import SCORE_DOT_BLACK_BORDER from "../assets/images/ui/score_dot_black_border.png";
import SCORE_DOT_EMPTY from "../assets/images/ui/score_dot_empty.png";
import SCORE_DOT_FILLED from "../assets/images/ui/score_dot_filled.png";
import BUTTONS_JSON from "../assets/images/world_objects/buttons.json";
import BUTTONS_IMG from "../assets/images/world_objects/buttons.png";
import BUOY1_JSON from "../assets/images/world_objects/water_objects/buoy1.json";
import BUOY1_IMG from "../assets/images/world_objects/water_objects/buoy1.png";
import BUOY4_JSON from "../assets/images/world_objects/water_objects/buoy4.json";
import BUOY4_IMG from "../assets/images/world_objects/water_objects/buoy4.png";
import DONUT_FLOAT2_JSON from "../assets/images/world_objects/water_objects/donut_float2.json";
import DONUT_FLOAT2_IMG from "../assets/images/world_objects/water_objects/donut_float2.png";
import FISHING_BOAT1_JSON from "../assets/images/world_objects/water_objects/fishing_boat1.json";
import FISHING_BOAT1_IMG from "../assets/images/world_objects/water_objects/fishing_boat1.png";
import FISHING_BOAT2_JSON from "../assets/images/world_objects/water_objects/fishing_boat2.json";
import FISHING_BOAT2_IMG from "../assets/images/world_objects/water_objects/fishing_boat2.png";
import WOOD_BOAT_JSON from "../assets/images/world_objects/water_objects/wood_boat.json";
import WOOD_BOAT_IMG from "../assets/images/world_objects/water_objects/wood_boat.png";
import DEER_SOUND from "../assets/sounds/deer.mp3";
import SQUIRREL_SOUND from "../assets/sounds/squirrel.mp3";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class ElandIslandsPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.ELAND_ISLANDS_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadElandIslandsAssets();
  }

  public create(): void {
    super.create();
    this.#createElandIslandsAnimations();
  }

  #loadElandIslandsAssets(): void {
    // Load campground level
    this.load.image(ASSET_KEYS.CAMPGROUND_BACKGROUND, CAMPGROUND_BACKGROUND);
    this.load.image(ASSET_KEYS.CAMPGROUND_FOREGROUND, CAMPGROUND_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.CAMPGROUND_LEVEL, CAMPGROUND_LEVEL);

    // Load grid puzzles
    this.load.json(ASSET_KEYS.GRID_LOGIC, GRID_LOGIC);
    this.load.json(ASSET_KEYS.CROSSWORDS, CROSSWORDS);
    this.load.json(ASSET_KEYS.SUDOKU, SUDOKU);

    // Load campground data
    this.load.json(ASSET_KEYS.EVENTS, CAMPGROUND_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, CAMPGROUND_NPCS);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, CAMPGROUND_READABLES);

    // Load buttons
    this.load.atlas(ASSET_KEYS.BUTTONS, BUTTONS_IMG, BUTTONS_JSON);

    // Load NPC data
    this.load.aseprite(ASSET_KEYS.SQUIRREL, SQUIRREL_IMG, SQUIRREL_JSON);
    this.load.aseprite(ASSET_KEYS.DEER, DEER_IMG, DEER_JSON);
    this.load.aseprite(
      ASSET_KEYS.DEER_CHOCOLATE,
      DEER_CHOCOLATE_IMG,
      DEER_CHOCOLATE_JSON,
    );
    this.load.aseprite(ASSET_KEYS.DEER_GOLD, DEER_GOLD_IMG, DEER_GOLD_JSON);
    this.load.aseprite(ASSET_KEYS.DEER_GREEN, DEER_GREEN_IMG, DEER_GREEN_JSON);

    // Load water objects
    this.load.aseprite(ASSET_KEYS.BUOY1, BUOY1_IMG, BUOY1_JSON);
    this.load.aseprite(ASSET_KEYS.BUOY4, BUOY4_IMG, BUOY4_JSON);
    this.load.aseprite(
      ASSET_KEYS.DONUT_FLOAT2,
      DONUT_FLOAT2_IMG,
      DONUT_FLOAT2_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.FISHING_BOAT1,
      FISHING_BOAT1_IMG,
      FISHING_BOAT1_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.FISHING_BOAT2,
      FISHING_BOAT2_IMG,
      FISHING_BOAT2_JSON,
    );
    this.load.aseprite(ASSET_KEYS.WOOD_BOAT, WOOD_BOAT_IMG, WOOD_BOAT_JSON);

    this.load.image(ASSET_KEYS.SCORE_DOT_BLACK_BORDER, SCORE_DOT_BLACK_BORDER);
    this.load.image(ASSET_KEYS.SCORE_DOT_EMPTY, SCORE_DOT_EMPTY);
    this.load.image(ASSET_KEYS.SCORE_DOT_FILLED, SCORE_DOT_FILLED);
    this.load.image(ASSET_KEYS.PAPER_ICON, PAPER_ICON);

    // Load sounds
    this.load.audio(ASSET_KEYS.DEER_SFX, DEER_SOUND);
    this.load.audio(ASSET_KEYS.SQUIRREL_SFX, SQUIRREL_SOUND);
  }

  #createElandIslandsAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.SQUIRREL);
    this.anims.createFromAseprite(ASSET_KEYS.DEER);
    this.anims.createFromAseprite(ASSET_KEYS.DEER_CHOCOLATE);
    this.anims.createFromAseprite(ASSET_KEYS.DEER_GOLD);
    this.anims.createFromAseprite(ASSET_KEYS.DEER_GREEN);
    this.anims.createFromAseprite(ASSET_KEYS.BUOY1);
    this.anims.createFromAseprite(ASSET_KEYS.BUOY4);
    this.anims.createFromAseprite(ASSET_KEYS.DONUT_FLOAT2);
    this.anims.createFromAseprite(ASSET_KEYS.FISHING_BOAT1);
    this.anims.createFromAseprite(ASSET_KEYS.FISHING_BOAT2);
    this.anims.createFromAseprite(ASSET_KEYS.WOOD_BOAT);
  }
}
