import * as Phaser from "phaser";
import { ASSET_KEYS, SQUIRREL_ANIMATION_KEYS } from "../../common/assets";
import {
  SQUIRREL_HIDE_COUNT,
  SQUIRREL_MAX_HP,
  SQUIRREL_SPEED,
} from "../../common/config";
import { DIRECTION, STORY_FLAG } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import { logger } from "../../common/logger";
import type { AnimationConfig } from "../../components/animation-component";
import { HidingComponent } from "../../components/hiding-component";
import { InputComponent } from "../../components/input-component";
import { CHARACTER_STATES } from "../../components/state-machine/states/character-states";
import { IdleState } from "../../components/state-machine/states/idle-state";
import { MoveState } from "../../components/state-machine/states/move-state";
import { CharacterObject } from "../common/character-object";
import { NPC_IDENTIFIER } from "../npcs/npc-constants";
import type { HidingPlace } from "../objects/campground/hiding_place";

export type SquirrelConfig = {
  scene: Phaser.Scene;
  hidingPlaces?: HidingPlace[];
  spawnPosition?: Phaser.Types.Math.Vector2Like;
};

export class Squirrel extends CharacterObject {
  #hidingComponent: HidingComponent;
  #visitedHidingPlaceIdentifiers = new Set<string>();
  #foundCount = 0;
  #hidingPlaces: HidingPlace[] = [];
  #isMovingToHidingPlace = false;

  constructor(config: SquirrelConfig) {
    // Define animations - reuse right animations for all directions
    const animationConfig: AnimationConfig = {
      IDLE_DOWN: {
        key: SQUIRREL_ANIMATION_KEYS.IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_UP: {
        key: SQUIRREL_ANIMATION_KEYS.IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_LEFT: {
        key: SQUIRREL_ANIMATION_KEYS.IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      IDLE_RIGHT: {
        key: SQUIRREL_ANIMATION_KEYS.IDLE_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_DOWN: {
        key: SQUIRREL_ANIMATION_KEYS.WALK_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_UP: {
        key: SQUIRREL_ANIMATION_KEYS.WALK_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_LEFT: {
        key: SQUIRREL_ANIMATION_KEYS.WALK_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
      WALK_RIGHT: {
        key: SQUIRREL_ANIMATION_KEYS.WALK_RIGHT,
        repeat: -1,
        ignoreIfPlaying: true,
      },
    };

    const spawnPosition = config.spawnPosition ?? { x: 500, y: 500 };
    super({
      id: `squirrel-${Phaser.Math.RND.uuid()}`,
      scene: config.scene,
      position: spawnPosition, // Placeholder position, may be updated later
      assetKey: ASSET_KEYS.SQUIRREL,
      frame: 0,
      isPlayer: false,
      animationConfig,
      speed: SQUIRREL_SPEED,
      inputComponent: new InputComponent(),
      isInvulnerable: true,
      maxHP: SQUIRREL_MAX_HP,
      shouldFlipLeft: true, // Enable automatic flipping for left direction
    });

    this.setOrigin(0, 0); // Top-left origin (standard)
    this.setDepth(3); // In front of the foreground

    // Set up idle and move states like NPCs
    this._stateMachine.addState(new IdleState(this));
    this._stateMachine.addState(new MoveState(this));
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);

    // Store hiding places reference
    this.#hidingPlaces = config.hidingPlaces || [];

    // Create hiding component
    this.#hidingComponent = new HidingComponent(this, {
      onHide: (hidingPlace) => {
        this.#onHide(hidingPlace);
      },
      onReveal: () => {
        this.#onReveal();
      },
    });
  }

  /**
   * Gets the current hiding place the squirrel is in, or null if not hiding
   */
  public get currentHidingPlace(): HidingPlace | null {
    return this.#hidingComponent.currentHidingPlace;
  }

  /**
   * Called by HidingComponent when hiding
   */
  #onHide(hidingPlace: HidingPlace): void {
    if (this.#isMovingToHidingPlace) {
      this.#isMovingToHidingPlace = false;
    }

    logger.info("Squirrel hid in: ", { hidingPlace: hidingPlace.identifier });
    this.#visitedHidingPlaceIdentifiers.add(hidingPlace.identifier);
    getSceneDataManager(this.scene).setFlagValue(
      STORY_FLAG.squirrel_location,
      hidingPlace.identifier,
    );

    // Stop any movement
    this.controls.reset();
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);
  }

  /**
   * Called by HidingComponent when revealed
   */
  #onReveal(): void {
    this.#foundCount++;

    // If found enough times, drop item
    if (this.#foundCount >= SQUIRREL_HIDE_COUNT) {
      this.#dropItem();
      return; // Don't move to new hiding place, squirrel will run off
    } else {
      // Move to a new hiding place
      this.#moveToRandomHidingPlace();
    }
  }

  /**
   * Moves the squirrel to a random unvisited hiding place
   */
  #moveToRandomHidingPlace(): void {
    if (this.#hidingPlaces.length === 0) {
      return;
    }

    // Filter to unvisited hiding places, or all if all have been visited
    const unvisited = this.#hidingPlaces.filter(
      (place) => !this.#visitedHidingPlaceIdentifiers.has(place.identifier),
    );
    const available = unvisited.length > 0 ? unvisited : this.#hidingPlaces;

    // Pick random hiding place
    const randomIndex = Phaser.Math.Between(0, available.length - 1);
    const targetPlace = available[randomIndex];

    // Don't move to the same place we're currently at
    if (targetPlace === this.currentHidingPlace) {
      // Pick a different one if available
      const others = available.filter(
        (place) => place !== this.currentHidingPlace,
      );
      if (others.length > 0) {
        const altIndex = Phaser.Math.Between(0, others.length - 1);
        this.#startMovingToHidingPlace(others[altIndex]);
        return;
      }
    }

    this.#startMovingToHidingPlace(targetPlace);
  }

  /**
   * Starts automated movement to a hiding place
   */
  #startMovingToHidingPlace(hidingPlace: HidingPlace): void {
    if (this.#isMovingToHidingPlace) {
      return; // Already moving
    }

    this.#isMovingToHidingPlace = true;
    this.scene.sound.play(ASSET_KEYS.SQUIRREL_SFX);
    this.#hidingComponent.setTargetHidingPlace(hidingPlace);

    // Calculate target position at center of hiding place
    const targetPos = {
      x: hidingPlace.x + hidingPlace.width / 2,
      y: hidingPlace.y + hidingPlace.height / 2,
    };

    // Start automated movement
    if (this.x > targetPos.x) {
      this.direction = DIRECTION.LEFT;
    } else {
      this.direction = DIRECTION.RIGHT;
    }
    this.scene.physics.moveTo(this, targetPos.x, targetPos.y, this.speed);
  }

  /**
   * Drops an item - shows dialogue, makes squirrel run off screen, then disables
   */
  #dropItem(): void {
    // Show dialogue
    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [
        "The squirrel dropped a marshmallow!",
        "...or what used to be one. It's more of a clump of dirt, twigs and leaves held together by some white paste now.",
        "I guess you could bring it back to Burnham?",
      ],
      choices: [],
    });

    // Determine direction to run off screen (left if x > 500, right if x < 500)
    // Use a large offset to ensure we go off screen
    const targetX = this.x > 500 ? this.x - 200 : this.x + 200;
    const targetY = this.y; // Keep same Y position

    // Run off screen
    // Set direction
    if (this.x > targetX) {
      this.direction = DIRECTION.LEFT;
    } else {
      this.direction = DIRECTION.RIGHT;
    }
    this.scene.physics.moveTo(this, targetX, targetY, this.speed);

    // Mark as completed and disable after a delay (movement is fire-and-forget)
    this.scene.time.delayedCall(2000, () => {
      const dataManager = getSceneDataManager(this.scene);
      dataManager.setFlagToCompleted(STORY_FLAG.squirrel_location);
      dataManager.undismissNpcExclamation(NPC_IDENTIFIER.BURNHAM);
      this.disableObject();
    });
  }

  /**
   * Restarts the squirrel's sequence - resets state and moves to a new hiding place
   */
  public restartObject(): void {
    // Reset visited hiding places
    this.#visitedHidingPlaceIdentifiers.clear();

    // Reset found count
    this.#foundCount = 0;

    // Stop any current movement
    this.#isMovingToHidingPlace = false;
    this.controls.reset();

    // If currently hiding, reveal
    if (this.currentHidingPlace) {
      this.#hidingComponent.revealFromHidingPlace();
    }

    // Reset to idle state
    this._stateMachine.setState(CHARACTER_STATES.IDLE_STATE);

    this.enableObject();
    // Move to a new random hiding place
    this.#moveToRandomHidingPlace();
  }

  /**
   * Public helper that initiates movement to a random hiding place if not already hiding.
   */
  public runToRandomHidingPlace(): void {
    if (this.currentHidingPlace || this.#isMovingToHidingPlace) {
      return;
    }
    this.#moveToRandomHidingPlace();
  }
}
