import {
  GridPuzzleType,
  type GridPuzzleSpec,
} from "./entities/dynamic-injections/grid_puzzle";

export const getIsolatedCells = (
  puzzle: GridPuzzleSpec,
): [number, number][] => {
  if (puzzle.puzzleType === GridPuzzleType.NURIKABE) {
    return getIsolatedCellsNurikabe(puzzle.solution);
  } else if (
    puzzle.puzzleType === GridPuzzleType.SLITHERLINK ||
    puzzle.puzzleType === GridPuzzleType.YAJILIN
  ) {
    return getIsolatedCellsYajilinSlitherlink(puzzle.solution);
  } else {
    throw new Error(`invalid puzzle type ${puzzle.puzzleType}`);
  }
};

export const getSurroundedCells = (
  puzzle: GridPuzzleSpec,
): [number, number][] => {
  if (puzzle.puzzleType === GridPuzzleType.NURIKABE) {
    return getSurroundedCellsNurikabe(puzzle.solution);
  } else if (puzzle.puzzleType === GridPuzzleType.SLITHERLINK) {
    return getSurroundedCellsSlitherlink(puzzle.solution);
  } else if (puzzle.puzzleType === GridPuzzleType.YAJILIN) {
    return getSurroundedCellsYajilin(puzzle.solution);
  } else {
    throw new Error(`invalid puzzle type ${puzzle.puzzleType}`);
  }
};

const getIsolatedCellsNurikabe = (solution: string[][]): [number, number][] => {
  return getIsolatedCellsHelper(solution, "W");
};

const getIsolatedCellsYajilinSlitherlink = (
  solution: string[][],
): [number, number][] => {
  return getIsolatedCellsHelper(solution, "I").concat(
    getIsolatedCellsHelper(solution, "L"),
  );
};

const getSurroundedCellsNurikabe = (
  solution: string[][],
): [number, number][] => {
  return solution
    .map((row, i) =>
      row.map<[number, number][]>((cell, j) => {
        let adjOpposite = 0;
        for (const d of [
          [0, 1],
          [1, 0],
          [-1, 0],
          [0, -1],
        ]) {
          const newI = i + d[0];
          const newJ = j + d[1];
          if (
            newI >= 0 &&
            newI < solution.length &&
            newJ >= 0 &&
            newJ < solution[0].length &&
            solution[newI][newJ] !== cell
          ) {
            adjOpposite += 1;
          }
        }

        return adjOpposite >= 3 ? [[i, j]] : [];
      }),
    )
    .flat(2);
};

const getSurroundedCellsSlitherlink = (
  solution: string[][],
): [number, number][] => {
  return solution
    .map((row, i) =>
      row.map<[number, number][]>((cell, j) => {
        let adjLoopSegments = 0;
        for (const d of [
          [0, 1],
          [1, 0],
          [-1, 0],
          [0, -1],
        ]) {
          const newI = i + d[0];
          const newJ = j + d[1];
          if (
            newI >= 0 &&
            newI < solution.length &&
            newJ >= 0 &&
            newJ < solution[0].length &&
            solution[newI][newJ] !== cell
          ) {
            // Case 1: if an adjacent cell has a different letter in the solution
            // then there's definitely a loop segment dividing them.
            adjLoopSegments += 1;
          } else if (
            (newI < 0 ||
              newI >= solution.length ||
              newJ < 0 ||
              newJ >= solution[0].length) &&
            cell === "I"
          ) {
            // Case 2: the cell is on a grid boundary and is inside the loop. In this case
            // the loop goes around the cell along the grid boundary.
            adjLoopSegments += 1;
          }
        }

        return adjLoopSegments >= 3 ? [[i, j]] : [];
      }),
    )
    .flat(2);
};

const getSurroundedCellsYajilin = (
  solution: string[][],
): [number, number][] => {
  return solution
    .map((row, i) =>
      row.map<[number, number][]>((cell, j) => {
        let adjOpposite = 0;
        for (const d of [
          [0, 1],
          [1, 0],
          [-1, 0],
          [0, -1],
        ]) {
          const newI = i + d[0];
          const newJ = j + d[1];
          if (
            newI >= 0 &&
            newI < solution.length &&
            newJ >= 0 &&
            newJ < solution[0].length &&
            solution[newI][newJ] === "L" &&
            solution[i][j] !== "L"
          ) {
            adjOpposite += 1;
          }
        }

        return adjOpposite >= 3 ? [[i, j]] : [];
      }),
    )
    .flat(2);
};

const getIsolatedCellsHelper = (
  solution: string[][],
  sentinel: string,
): [number, number][] => {
  return solution
    .map((row, i) =>
      row.map<[number, number][]>((cell, j) =>
        cell === sentinel ? [[i, j]] : [],
      ),
    )
    .flat(2);
};
