import type { MinesweeperInjectionType } from "../../entities/dynamic-injections/minesweeper";
import type {
  DELIVERABLE_FRAME_KEYS,
  TreasureFrameKey,
  CAMPGROUND_BUTTON_FRAME_KEYS,
} from "../assets";
import { type StoryFlag } from "../constants";
import type { CharacterColor, Direction } from "../types";
import type * as TILED_CONSTANTS from "./constants";

export type TiledObject = {
  height: number;
  width: number;
  x: number;
  y: number;
};

export type TiledObjectProperty = {
  name: string;
  type: string;
  value: string | number | boolean;
};

export type TiledObjectWithProperties = {
  properties: TiledObjectProperty[];
} & TiledObject;

export type TiledRoomObject = {
  id: number;
  foregroundOverride: string;
} & TiledObject;

export type TiledAnimatedObject = {
  texture: string;
  effect?: AnimatedObjectEffect;
  trigger?: string;
} & TiledObject;

export type AnimatedObjectEffect =
  keyof typeof TILED_CONSTANTS.ANIMATED_OBJECT_EFFECT;

export type TriggerInfo = {
  type: TriggerType;
  ids: number[];
};

export type TriggerType = keyof typeof TILED_CONSTANTS.TRIGGER_TYPE;

export type TiledDoorObject = {
  id: number;
  direction: Direction;
  doorType?: DoorType; // Default to "OPEN"
  isLevelTransition?: boolean; // Default to false
  isUnlocked?: boolean; // Default to false
  targetDoorId?: number; // Default to 0
  targetLevel?: string; // Default to ""
  targetRoomId?: number; // Default to 0
  trapDoorTrigger?: TriggerInfo; // Default to { triggerType: "NONE", targetIds: [] }
  requiredFlags?: string[]; // Optional story flag requirements (must be completed)
  requiredFrontendFlags?: Record<string, string>; // Optional frontend flag requirements (must be completed)
  assetKey?: string;
  openFrameName?: string;
  closedFrameName?: string;
  animation?: string; // Deprecated: use animateWalk instead
  animateWalk?: boolean; // Default false - if true, animate walk using door direction
} & TiledObject;

export type DoorType = keyof typeof TILED_CONSTANTS.DOOR_TYPE;

export type TiledBuriedTreasureObject = {
  texture: TreasureFrameKey;
  interactionId?: string;
  storyFlag?: string;
  sparkle?: boolean;
  discoverableByProximity: boolean;
} & TiledObject;

export type TiledMiningObject = {
  identifier: number;
  gemFrame: string;
} & TiledObject;

export enum CampgroundControlsType {
  RED_BUTTON = "RED_BUTTON",
  GREEN_BUTTON = "GREEN_BUTTON",
  BLUE_BUTTON = "BLUE_BUTTON",
  TIMER = "TIMER",
  MANUAL_INDEX = "MANUAL_INDEX",
}

export type TiledControlsObject<T> = {
  controlType: T;
  pressedTexture?: CampgroundButtonFrameKeys;
  unpressedTexture?: CampgroundButtonFrameKeys;
} & TiledObject;

export type CampgroundButtonFrameKeys =
  keyof typeof CAMPGROUND_BUTTON_FRAME_KEYS;

export type TiledChestObject = {
  id: number;
  contents: ChestReward;
  requiresBossKey?: boolean;
  revealChestTrigger?: TriggerInfo;
  storyFlag?: StoryFlag;
} & TiledObject;

export type ChestReward = keyof typeof TILED_CONSTANTS.CHEST_REWARD;

export type TiledInteractiveCandleObject = {
  id: string;
} & TiledObject;

export type TiledColorClueObject = {
  number: number;
  revealClueTrigger: RevealTriggerType;
  visibleTo: CharacterColor[];
  minesweeperInjectionType: MinesweeperInjectionType;
} & TiledObject;

export type TiledPushConfig = {
  pushable: boolean;
  requiredLevel?: string;
  requiredRoom?: number;
};

export type TiledDeliverableObject = {
  id: number;
  revealDeliverableTrigger: RevealTriggerType;
  texture: DeliverableTexture;
  pushConfig?: TiledPushConfig;
  maxHoldTime: number;
} & TiledObject;

export enum DeskType {
  EXAM = "exam",
  EMPTY_DESK = "empty_desk",
  PENCIL_BAG = "pencil_bag",
  CLOSED_BOOK = "closed_book",
}

export type TiledRegiDeskObject = {
  id: number;
  deskType: DeskType;
} & TiledObject;

export type DeliverableTexture = keyof typeof DELIVERABLE_FRAME_KEYS;

export type TiledDeliveryBoxObject = {
  id: number;
  contents: ChestReward;
  deliverableNumber: number;
  deliverableType: DeliverableTexture;
} & TiledObject;

export type TiledDiggableStructureObject = {
  texture: DiggableStructureTexture;
  storyFlag?: string;
} & TiledObject;

export type DiggableStructureTexture =
  keyof typeof TILED_CONSTANTS.DIGGABLE_STRUCTURE_TEXTURE;

export type TiledDynamicInjectionObject = {
  id: number;
  injectionType: DynamicInjectionType;
  offset: number;
  storyFlag?: string;
} & TiledObject;

export type MinesweeperInjectionObject = {
  id: number;
  injectionType:
    | "MINESWEEPER_STANDARD"
    | "MINESWEEPER_BILLIARDS"
    | "MINESWEEPER_POKEMON";
  offset: number;
} & TiledObject;

export type DynamicInjectionType =
  keyof typeof TILED_CONSTANTS.DYNAMIC_INJECTION_TYPE;

export type TiledEffectObject = {
  effect: string;
} & TiledObject;

export type TiledEnemyObject = {
  enemyType: EnemyType;
  revealEnemyTrigger: RevealTriggerType;
  visibleTo: CharacterColor[];
  initialDirection?: Direction;
} & TiledObject;

export type EnemyType = keyof typeof TILED_CONSTANTS.ENEMY_TYPE;

export type TiledEventObject = {
  eventId: string;
  isMovementPattern?: boolean; // If true, this is a movement pattern event zone (requires 5s of movement, resets after 0.5s of standing still)
} & TiledObject;

export type TiledFishingSpotObject = {
  texture?: string;
  storyFlag?: string;
} & TiledObject;

export type TiledFloorToggleObject = {
  color: FloorToggleColor;
} & TiledObject;

export type FloorToggleColor = keyof typeof TILED_CONSTANTS.FLOOR_TOGGLE_COLOR;

export type TiledGateObject = {
  storyFlag?: string;
  texture: string;
  order: number; // Sequence order (1, 2, 3, ...)
} & TiledObject;

export type TiledHidingPlaceObject = {
  identifier: string;
  requiresDirection?: boolean;
  requiredDirection?: Direction;
} & TiledObject;

export type TiledNpcObject = {
  identifier: NPCIdentifier;
} & TiledObject;

export type NPCIdentifier = string;

export type TiledPotObject = TiledObject;

export type TiledPushableObject = {
  texture?: string;
} & TiledObject;

export type TiledPushGoalObject = {
  identifier?: string;
} & TiledObject;

export type TiledReadableObject = {
  identifier: string;
} & TiledObject;

export type TiledPlatformObject = {
  direction: Direction;
  blockingId: number;
} & TiledObject;

export type TiledRockObject = {
  blockingId?: number;
} & TiledObject;

export type TiledLavaObject = TiledObject;

export type TiledRegiObject = {
  id: "DOT" | "DASH" | "ENTRY";
} & TiledObject;

export type TiledSwitchObject = {
  id: number;
  action: SwitchAction;
  targetIds: number[];
  texture: SwitchTexture;
} & TiledObject;

export type SwitchAction = keyof typeof TILED_CONSTANTS.SWITCH_ACTION;

export type SwitchTexture = keyof typeof TILED_CONSTANTS.SWITCH_TEXTURE;

export type RevealTriggerType = keyof typeof TILED_CONSTANTS.REVEAL_TRIGGER;

export type TrapType = keyof typeof TILED_CONSTANTS.TRAP_TYPE;

export type TiledTrapObject = {
  trapType: TrapType;
  direction: Direction; // Direction for directional traps (e.g., flame traps)
  pattern?: number; // Pattern type (default: 0)
} & TiledObject;

export type TiledVehicleObject = {
  texture: VehicleTexture;
  targetRoomId?: number;
  targetDoorId?: number;
  vehicleId?: string;
  direction?: string;
} & TiledObject;

export type VehicleTexture = keyof typeof TILED_CONSTANTS.VEHICLE_TEXTURE;
