import * as Phaser from "phaser";
import {
  ASSET_KEYS,
  CAMPGROUND_BUTTON_FRAME_KEYS,
} from "../../../common/assets";
import { INTERACTIVE_OBJECT_TYPE } from "../../../common/constants";
import { type TiledControlsObject } from "../../../common/tiled/types";
import type { CustomObject } from "../../../common/types";
import { InteractiveObjectComponent } from "../../../components/interactive-object-component";

export class CampgroundButton<T>
  extends Phaser.Physics.Arcade.Image
  implements CustomObject
{
  private config: TiledControlsObject<T>;

  constructor(
    scene: Phaser.Scene,
    config: TiledControlsObject<T>,
    onClick: (controlType: T) => boolean,
  ) {
    super(
      scene,
      config.x,
      config.y,
      ASSET_KEYS.BUTTONS,
      CAMPGROUND_BUTTON_FRAME_KEYS[config.pressedTexture ?? "blue_pressed.png"],
    );

    this.config = config;

    // The button assets are 20x20.
    this.setScale(0.8, 0.8);
    scene.add.existing(this);
    scene.physics.add.existing(this);
    this.setOrigin(0, 0).setImmovable(true);

    new InteractiveObjectComponent(this, INTERACTIVE_OBJECT_TYPE.AUTO, () => {
      this.setFrame(
        CAMPGROUND_BUTTON_FRAME_KEYS[
          config.pressedTexture ?? "blue_pressed.png"
        ],
      );
      const correct = onClick(config.controlType);
      if (correct) {
        setTimeout(() => {
          if (this.active) {
            this.setFrame(
              CAMPGROUND_BUTTON_FRAME_KEYS[
                config.unpressedTexture ?? "blue_unpressed.png"
              ],
            );
          }
        }, 300);
      }
      return true;
    });

    this.disableObject();
  }

  public activate(): void {
    this.active = true;
  }

  public deactivate(): void {
    this.active = false;
  }

  public press(): void {
    this.setFrame(
      CAMPGROUND_BUTTON_FRAME_KEYS[
        this.config.pressedTexture ?? "blue_pressed.png"
      ],
    );
  }

  public unPress(): void {
    this.setFrame(
      CAMPGROUND_BUTTON_FRAME_KEYS[
        this.config.unpressedTexture ?? "blue_unpressed.png"
      ],
    );
  }

  public disableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = false;
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    (this.body as Phaser.Physics.Arcade.Body).enable = true;
    this.visible = true;
    this.active = true;
  }
}
