import * as Phaser from "phaser";
import { LINE_COLOR_INT } from "../../common/eland-islands";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { GridPuzzle, type GridPuzzleSpec } from "./grid_puzzle";

enum Arrow {
  UP = "^",
  DOWN = "v",
  LEFT = "<",
  RIGHT = ">",
}

export class Yajilin extends GridPuzzle<GridPuzzleSpec> {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: GridPuzzleSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();

    this.add(this.makeGrid());
    this.add(this.#makeNumbers());
  }

  #makeNumbers(): Phaser.GameObjects.GameObject[] {
    return this.asset.grid
      .map((row, i) =>
        row.map((cell, j) => {
          if (cell === " ") {
            return;
          }

          const coord = this.cellCoord(i, j);
          const rectangle = new Phaser.GameObjects.Rectangle(
            this.scene,
            coord.x + coord.width / 2,
            coord.y + coord.height / 2,
            this.object.width / this.dim,
            this.object.height / this.dim,
            0x00000,
          );
          const arrow = cell[1] as Arrow;
          const text = this.makeText(coord, cell[0], 16);
          if (arrow === Arrow.UP || arrow === Arrow.DOWN) {
            Phaser.Display.Align.In.Center(text, rectangle, -2);
          } else if (arrow === Arrow.LEFT || arrow === Arrow.RIGHT) {
            Phaser.Display.Align.In.BottomCenter(text, rectangle);
          } else {
            throw new Error(`Bug: invalid arrow ${arrow}`);
          }

          return this.#makeArrow(arrow, rectangle).concat(text);
        }),
      )
      .flat(2)
      .filter((obj) => obj !== undefined);
  }

  #makeArrow(
    arrow: Arrow,
    rectangle: Phaser.GameObjects.Rectangle,
  ): Phaser.GameObjects.GameObject[] {
    const cellWidth = this.object.width / this.dim;
    const cellHeight = this.object.height / this.dim;

    let line: Phaser.GameObjects.Line;
    if (arrow === Arrow.UP || arrow === Arrow.DOWN) {
      line = new Phaser.GameObjects.Line(
        this.scene,
        0,
        0,
        0,
        0,
        0,
        cellHeight - 6,
      );
      Phaser.Display.Align.In.RightCenter(line, rectangle, -4);
    } else if (arrow === Arrow.LEFT || arrow === Arrow.RIGHT) {
      line = new Phaser.GameObjects.Line(
        this.scene,
        0,
        0,
        0,
        0,
        cellWidth - 6,
        0,
      );
      Phaser.Display.Align.In.TopCenter(line, rectangle, 0, -4);
    } else {
      throw new Error(`Bug: invalid arrow type ${arrow}`);
    }

    line.setStrokeStyle(1, LINE_COLOR_INT);

    const triangleWidth = 6;
    const triangleHeight = 6;
    let triangle = new Phaser.GameObjects.Triangle(
      this.scene,
      0,
      0,
      0,
      0,
      (-1 * triangleWidth) / 2,
      triangleHeight,
      triangleWidth / 2,
      triangleHeight,
    );
    // I don't understand where the padding numbers come from here, I just tweaked them until they looked good.
    if (arrow === Arrow.UP) {
      triangle = Phaser.Display.Align.In.TopRight(triangle, rectangle, 1, -2);
    } else if (arrow === Arrow.DOWN) {
      triangle.setRotation(Math.PI);
      Phaser.Display.Align.In.BottomRight(triangle, rectangle, -5, -2);
    } else if (arrow === Arrow.LEFT) {
      triangle.setRotation((3 * Math.PI) / 2);
      Phaser.Display.Align.In.TopLeft(triangle, rectangle, -3, 2);
    } else if (arrow === Arrow.RIGHT) {
      triangle.setRotation(Math.PI / 2);
      Phaser.Display.Align.In.TopRight(triangle, rectangle, -3, -4);
    } else {
      throw new Error(`Bug! Invalid arrow ${arrow}`);
    }

    triangle.setFillStyle(LINE_COLOR_INT);

    return [line, triangle];
  }
}
