import * as Phaser from "phaser";
import { LINE_COLOR_INT, LINE_COLOR_STRING } from "../../common/eland-islands";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { type CustomObject } from "../../common/types";

const BAR_WIDTH = 3;
const OFFSET = BAR_WIDTH / 2;

export enum GridPuzzleType {
  SLITHERLINK = "SLITHERLINK",
  NURIKABE = "NURIKABE",
  YAJILIN = "YAJILIN",
  BARRED_CROSSWORD = "BARRED_CROSSWORD",
  BLOCKED_CROSSWORD = "BLOCKED_CROSSWORD",
  JIGSAW_SUDOKU = "JIGSAW_SUDOKU",
  THERMO_SUDOKU = "THERMO_SUDOKU",
  KILLER_SUDOKU = "KILLER_SUDOKU",
}

export type GridPuzzleSpec = {
  puzzleType: GridPuzzleType;
  grid: string[][];
  solution: string[][];
};

export type Coord = { x: number; y: number; width: number; height: number };

export class GridPuzzle<T extends GridPuzzleSpec>
  extends Phaser.GameObjects.Container
  implements CustomObject
{
  protected asset: T;
  protected object: TiledDynamicInjectionObject;
  protected dim: number;

  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: T,
  ) {
    super(scene, tiledObject.x, tiledObject.y);
    this.object = tiledObject;
    this.asset = asset;
    this.dim = 5;

    this.disableObject();
    this.setToBack();
  }

  protected makeNumbers(): Phaser.GameObjects.Text[] {
    return this.asset.grid
      .map((row, i) =>
        row
          .map((cell, j) => {
            if (cell.length === 0) {
              return;
            }

            const coord = this.cellCoord(i, j);
            const rectangle = new Phaser.GameObjects.Rectangle(
              this.scene,
              coord.x + coord.width / 2,
              coord.y + coord.height / 2,
              this.object.width / this.dim,
              this.object.height / this.dim,
              LINE_COLOR_INT,
            );

            const text = this.makeText(coord, /\d+/.exec(cell)?.[0] ?? "", 20);
            Phaser.Display.Align.In.Center(text, rectangle);
            return text;
          })
          .filter((text) => text !== undefined),
      )
      .flat();
  }

  protected makeGrid(): Phaser.GameObjects.Rectangle[] {
    return Array.from(Array(this.dim).keys())
      .map((i) =>
        Array.from(Array(this.dim).keys()).map((j) => {
          const coord = this.cellCoord(i, j);
          return new Phaser.GameObjects.Rectangle(
            this.scene,
            coord.x + coord.width / 2,
            coord.y + coord.height / 2,
            coord.width,
            coord.height,
          ).setStrokeStyle(1, LINE_COLOR_INT);
        }),
      )
      .flat();
  }

  protected makeBars(): Phaser.GameObjects.GameObject[] {
    return this.asset.grid
      .map((row, i) =>
        row.map((cell, j) => {
          const contents = /[\d\s]+/.exec(cell)?.[0];
          if (!contents) {
            return;
          }

          const coord = this.cellCoord(i, j);
          const rectangle = new Phaser.GameObjects.Rectangle(
            this.scene,
            coord.x + coord.width / 2,
            coord.y + coord.height / 2,
            this.object.width / this.dim,
            this.object.height / this.dim,
            LINE_COLOR_INT,
          );

          const idx = cell.indexOf(contents);
          const bars: Phaser.GameObjects.GameObject[] = [];
          for (let k = 0; k < cell.length; k++) {
            const char = cell[k];
            if (char === "_") {
              const bar = this.makeHorizontalBorder(coord.width);
              Phaser.Display.Align.In.BottomCenter(bar, rectangle, 0, OFFSET);
              bars.push(bar);
            } else if (char === "-") {
              const bar = this.makeHorizontalBorder(coord.width);
              Phaser.Display.Align.In.TopCenter(bar, rectangle, 0, OFFSET);
              bars.push(bar);
            } else if (char === "|" && k < idx) {
              const bar = this.makeVerticalBorder(coord.height);
              Phaser.Display.Align.In.LeftCenter(bar, rectangle, OFFSET, 0);
              bars.push(bar);
            } else if (char === "|" && k > idx) {
              const bar = this.makeVerticalBorder(coord.height);
              Phaser.Display.Align.In.RightCenter(bar, rectangle, OFFSET, 0);
              bars.push(bar);
            }
          }

          return bars;
        }),
      )
      .flat(2)
      .filter((bar) => bar !== undefined);
  }

  private makeVerticalBorder(height: number): Phaser.GameObjects.Rectangle {
    return new Phaser.GameObjects.Rectangle(
      this.scene,
      0,
      0,
      BAR_WIDTH,
      height,
      LINE_COLOR_INT,
    );
  }

  private makeHorizontalBorder(width: number): Phaser.GameObjects.Rectangle {
    return new Phaser.GameObjects.Rectangle(
      this.scene,
      0,
      0,
      width,
      BAR_WIDTH,
      LINE_COLOR_INT,
    );
  }

  protected makeText(coord: Coord, text: string, fontSize: number) {
    return new Phaser.GameObjects.Text(this.scene, coord.x, coord.y, text, {
      color: LINE_COLOR_STRING,
      align: "center",
      fontSize,
      fontFamily: "Arial",
    });
  }

  protected cellCoord(i: number, j: number): Coord {
    const width = this.object.width / this.dim;
    const height = this.object.height / this.dim;
    return {
      x: height * j,
      y: width * i,
      width,
      height,
    };
  }

  enableObject(): void {
    this.setActive(true);
    this.setVisible(true);
    this.setToBack();
  }
  disableObject(): void {
    this.setActive(false);
    this.setVisible(false);
  }
}
