import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import ElandIslandsGameManager from "../../../components/overworld/ElandIslandsGameManager";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadElandIslandsScenes } from "../gameworld/scene-loaders/eland-islands";
import ElandIslandsBody from "./ElandIslandsBody";
import { type ElandIslandsState } from "./types";

const ElandIslandsManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: ElandIslandsState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="eland_islands"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadElandIslandsScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <>
              <ElandIslandsGameManager />
              <ElandIslandsBody
                state={state}
                teamState={teamState}
                gameNode={gameNode}
              />
            </>
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("eland_islands-root");
if (elem) {
  const { initialElandIslandsState: state, initialTeamState } =
    window as unknown as {
      initialElandIslandsState: ElandIslandsState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <ElandIslandsManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount ElandIslandsManager because #eland_islands-root was nowhere to be found",
  );
}
