import type * as Phaser from "phaser";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { CrosswordGridPuzzle, type CrosswordGridSpec } from "./crossword";

export class BarredCrossword extends CrosswordGridPuzzle {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: CrosswordGridSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();
    this.add(this.makeGrid());
    this.add(this.makeNumbers());
    this.add(this.makeBars());
  }
}
