import * as Phaser from "phaser";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { GridPuzzle, type GridPuzzleSpec } from "./grid_puzzle";

export class Slitherlink extends GridPuzzle<GridPuzzleSpec> {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: GridPuzzleSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();

    this.add(this.#makeDots());
    this.add(this.makeNumbers());
  }

  #makeDots(): Phaser.GameObjects.Rectangle[] {
    // We just create the dot in the upper-left corner of the cell in this loop, so to get
    // the number of dots we need we add an extra row and column.
    return Array.from(Array(this.dim + 1).keys())
      .map((i) =>
        Array.from(Array(this.dim + 1).keys()).map((j) => {
          const coord = this.cellCoord(i, j);
          return new Phaser.GameObjects.Rectangle(
            this.scene,
            coord.x - 1,
            coord.y - 1,
            2,
            2,
            0x00000,
          );
        }),
      )
      .flat();
  }
}
