import * as Phaser from "phaser";
import { LINE_COLOR_INT } from "../../common/eland-islands";
import { CUSTOM_EVENTS, EVENT_BUS } from "../../common/event-bus";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { type NPC } from "../npcs/npc";
import { NPC_IDENTIFIER } from "../npcs/npc-constants";
import { type EventSequence } from "../npcs/npc-types";
import { GridPuzzle, type GridPuzzleSpec } from "./grid_puzzle";

export type CrosswordGridSpec = GridPuzzleSpec & {
  across: [string, string][];
  down: [string, string][];
};

export class CrosswordGridPuzzle extends GridPuzzle<CrosswordGridSpec> {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: CrosswordGridSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();
    EVENT_BUS.addListener(
      CUSTOM_EVENTS.NPC_INTERACTION,
      (data: { sequence: EventSequence; npc: NPC }) => {
        if (data.npc.identifier === NPC_IDENTIFIER.CROSSWORD) {
          navigator.clipboard
            .write([
              new ClipboardItem({
                "text/html": new Blob([this.generateClipboardContent()], {
                  type: "text/html",
                }),
                "text/plain": new Blob([this.generatePlaintextContent()], {
                  type: "text/plain",
                }),
              }),
            ])
            .catch((): void => {
              console.error("error");
            });
        }
      },
    );
  }

  protected makeNumbers(): Phaser.GameObjects.Text[] {
    return this.asset.grid
      .map((row, i) =>
        row
          .map((cell, j) => {
            if (cell.length === 0 || cell === "X") {
              return;
            }

            const coord = this.cellCoord(i, j);
            const rectangle = new Phaser.GameObjects.Rectangle(
              this.scene,
              coord.x + coord.width / 2,
              coord.y + coord.height / 2,
              this.object.width / this.dim,
              this.object.height / this.dim,
              LINE_COLOR_INT,
            );

            const text = this.makeText(coord, /\d+/.exec(cell)?.[0] ?? "", 12);
            Phaser.Display.Align.In.TopLeft(text, rectangle, -2, -1);
            return text;
          })
          .filter((text) => text !== undefined),
      )
      .flat();
  }

  private generateClipboardContent(): string {
    const content =
      `<table><thead><th style="text-align: start">Across</th><th style="text-align: start">Down</th></thead><tbody>
        ${Array.from(
          Array(
            Math.max(
              Object.keys(this.asset.across).length,
              Object.keys(this.asset.down).length,
            ),
          ).keys(),
        )
          .map(
            (index) =>
              `<tr><td>${this.asset.across[index]?.join(": ") ?? ""}</td><td>${this.asset.down[index]?.join(": ") ?? ""}</td></tr>`,
          )
          .join("")}</tbody></table>`.replaceAll("\n", "");
    return content;
  }

  private generatePlaintextContent(): string {
    const maxLength = Math.max(
      Object.keys(this.asset.across).length,
      Object.keys(this.asset.down).length,
    );
    const lines: string[] = ["Across\tDown"];
    for (let index = 0; index < maxLength; index++) {
      const across = this.asset.across[index]?.join(": ") ?? "";
      const down = this.asset.down[index]?.join(": ") ?? "";
      lines.push(`${across}\t${down}`);
    }
    return lines.join("\n");
  }
}
