// We specify in the appendix that Y is a consonant.
const VOWELS = ["A", "E", "I", "O", "U"];
const PRIMES = [2, 3, 5];

// TODO: make a list that includes all manual entries before Saturday testsolve.
const EASY_MANUAL_ENTRIES = ["◯ A", "▢ A", "△ B", "☾ B", "☾ D", "▢ E"];
const MEDIUM_MANUAL_ENTRIES = ["△ A", "☆ A", "◯ B", "△ C", "▢ D", "☾ E"];
const HARD_MANUAL_ENTRIES = ["☾ A", "☆ B", "◯ C", "▢ C", "☾ C", "△ D", "☆ D"];
const COMBINED_MANUAL_ENTRIES = ["▢ B", "☆ C", "◯ D", "◯ E", "△ E", "☆ E"];
const SQUIRREL_ROOM_ID = 1;
const CLIENT_RETRY_ATTEMPTS = 3;
const CLIENT_RETRY_INITIAL_DELAY_MS = 500;
const CLIENT_RETRY_BACKOFF_MULTIPLIER = 2;

const delay = (ms: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

const retryClientCall = async <T>(operation: () => Promise<T>): Promise<T> => {
  let delayMs = CLIENT_RETRY_INITIAL_DELAY_MS;
  for (let attempt = 0; attempt < CLIENT_RETRY_ATTEMPTS; attempt += 1) {
    try {
      return await operation();
    } catch (err) {
      if (attempt === CLIENT_RETRY_ATTEMPTS - 1) {
        throw err;
      }
      await delay(delayMs);
      delayMs *= CLIENT_RETRY_BACKOFF_MULTIPLIER;
    }
  }
  throw new Error("Retry attempts exhausted.");
};

const isVowel = (letter: string): boolean => VOWELS.includes(letter);

const isConsonant = (letter: string): boolean =>
  !VOWELS.includes(letter) && letter !== ".";

const getManualEntry = (currentScore: number, manualIndex: number): string => {
  if (currentScore < 3) {
    return EASY_MANUAL_ENTRIES[manualIndex % EASY_MANUAL_ENTRIES.length];
  }
  if (currentScore < 6) {
    return MEDIUM_MANUAL_ENTRIES[manualIndex % MEDIUM_MANUAL_ENTRIES.length];
  }
  if (currentScore < 9) {
    return HARD_MANUAL_ENTRIES[manualIndex % HARD_MANUAL_ENTRIES.length];
  }

  return COMBINED_MANUAL_ENTRIES[manualIndex % COMBINED_MANUAL_ENTRIES.length];
};

const MANUAL: Record<
  string,
  (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => CampgroundControlsType
> = {
  "◯ A": (
    _id: number,
    _logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the crossword is barred, press the button on your left, otherwise, if the crossword is american, press the green button, otherwise, press the red button
    crossword.puzzleType === GridPuzzleType.BARRED_CROSSWORD
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "◯ B": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) =>
    // If the top right corner contains a prime number, press the middle button, otherwise, press the red button
    PRIMES.includes(Number(sudoku.solution[0][4]))
      ? CampgroundControlsType.GREEN_BUTTON
      : CampgroundControlsType.RED_BUTTON,
  "◯ C": (
    _id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If there are more than 5 surrounded tiles, press the red button, otherwise, press the blue button
    getSurroundedCells(logic).length > 5
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.BLUE_BUTTON,
  "◯ D": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) => {
    // If an E is surrounded, press the green button, otherwise, press the left button
    const surrounded = getSurroundedCells(logic);
    for (const [i, j] of surrounded) {
      if (crossword.solution[i][j] === "E") {
        return CampgroundControlsType.GREEN_BUTTON;
      }
    }

    return CampgroundControlsType.RED_BUTTON;
  },
  "◯ E": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => {
    const isolated = getIsolatedCells(logic);
    // If the center tile is an isolated consonant prime, press the rightmost button, otherwise, press the centermost button
    const isIsolated = isolated.some((cell) => cell[0] === 2 && cell[1] === 2);
    const isPrime = PRIMES.includes(Number(sudoku.solution[2][2]));
    return isIsolated && isConsonant(crossword.solution[2][2]) && isPrime
      ? CampgroundControlsType.BLUE_BUTTON
      : CampgroundControlsType.GREEN_BUTTON;
  },
  "△ A": (
    _id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the center tile is isolated, press the middle button, otherwise, press the button on the left
    getIsolatedCells(logic).some((coords) => coords[0] === 2 && coords[1] === 2)
      ? CampgroundControlsType.GREEN_BUTTON
      : CampgroundControlsType.RED_BUTTON,
  "△ B": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) =>
    // If there is a thermometer, press the red button, otherwise, press the blue button
    sudoku.puzzleType === GridPuzzleType.THERMO_SUDOKU
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.BLUE_BUTTON,
  "△ C": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) =>
    // If the bottom right corner is <3, press the red button, otherwise, press the green button
    Number(sudoku.solution[4][4]) < 3
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "△ D": (
    id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the crossword’s main diagonal is a valid scrabble word, press the red button, otherwise, press the green button
    [2, 7].includes(id)
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "△ E": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) => {
    // If most vowels are isolated, press the red button, otherwise, press the middle button
    const isolated = getIsolatedCells(logic);
    let isolatedVowels = 0;
    let vowelCount = 0;

    for (const [i, row] of crossword.solution.entries()) {
      for (const [j, cell] of row.entries()) {
        if (isVowel(cell)) {
          vowelCount += 1;

          for (const coords of isolated) {
            if (coords[0] === i && coords[1] === j) {
              isolatedVowels += 1;
            }
          }
        }
      }
    }

    return isolatedVowels > vowelCount - isolatedVowels
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.GREEN_BUTTON;
  },
  "▢ A": (
    _id: number,
    _logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the crossword contains a black square, press the 3rd button from the right, otherwise, press the 2nd button from the left
    crossword.grid.some((row) => row.some((cell) => cell === "X"))
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "▢ B": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => {
    // If a letter overlaps with its a1z26 counterpart, press the blue button, otherwise, press the red button
    for (let i = 0; i < 5; i++) {
      for (let j = 0; j < 5; j++) {
        const character = crossword.solution[i][j];
        const target = character.charCodeAt(0) - "A".charCodeAt(0) + 1;
        if (
          sudoku.solution[i][j] === target.toString() ||
          logic.grid[i][j].includes(target.toString())
        ) {
          return CampgroundControlsType.BLUE_BUTTON;
        }
      }
    }
    return CampgroundControlsType.RED_BUTTON;
  },
  "▢ C": (
    id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If there are more isolated tiles than non-isolated tiles, press the green button, otherwise, press the left button
    getIsolatedCells(logic).length > Math.floor(25 / 2)
      ? CampgroundControlsType.GREEN_BUTTON
      : CampgroundControlsType.RED_BUTTON,
  "▢ D": (
    _id: number,
    _logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the first letter in reading order is in the first half of the alphabet, press the button whose color’s first letter isn’t, otherwise, press the button whose color’s first letter is earliest in the alphabet
    (crossword.solution[0].find((value) => value !== ".") ?? "Z") <= "M"
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.BLUE_BUTTON,
  "▢ E": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) =>
    // If there is a killer cage, press the right button, otherwise, press the green button
    sudoku.puzzleType === GridPuzzleType.KILLER_SUDOKU
      ? CampgroundControlsType.BLUE_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "☾ A": (
    _id: number,
    _logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) => {
    // If the crossword has more vowels than consonants, press the right button, otherwise, press the red one
    const counts = crossword.solution
      .flat()
      .filter((cell) => cell !== ".")
      .reduce(
        (acc, curr) => {
          if (isVowel(curr)) {
            acc.vowels += 1;
          } else {
            acc.consonants += 1;
          }

          return acc;
        },
        { vowels: 0, consonants: 0 },
      );
    return counts.vowels > counts.consonants
      ? CampgroundControlsType.BLUE_BUTTON
      : CampgroundControlsType.RED_BUTTON;
  },
  "☾ B": (
    _id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the logic puzzle’s genre is loop, press the red button, otherwise, press the rightmost button
    logic.puzzleType === GridPuzzleType.SLITHERLINK ||
    logic.puzzleType === GridPuzzleType.YAJILIN
      ? CampgroundControlsType.RED_BUTTON
      : CampgroundControlsType.BLUE_BUTTON,
  "☾ C": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the sudoku contains exactly five fives, press the blue button, otherwise, press the fourth button
    // Every sudoku contains five fives by the rules of sudoku
    CampgroundControlsType.BLUE_BUTTON,
  "☾ D": (
    _id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the logic grid has arrows, press the middle button, otherwise, press the blue button
    logic.puzzleType === GridPuzzleType.YAJILIN
      ? CampgroundControlsType.GREEN_BUTTON
      : CampgroundControlsType.BLUE_BUTTON,
  "☾ E": (
    _id: number,
    _logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the centermost letter is a vowel, press the button whose name has 2 unique vowels, otherwise press the centermost button
    isVowel(crossword.solution[2][2])
      ? CampgroundControlsType.BLUE_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "☆ A": (
    id: number,
    logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the centermost leftmost tile is surrounded, press the rightmost button, otherwise, press the centermost button
    getSurroundedCells(logic).some(
      (coords) => coords[0] === 2 && coords[1] === 0,
    )
      ? CampgroundControlsType.BLUE_BUTTON
      : CampgroundControlsType.GREEN_BUTTON,
  "☆ B": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => {
    // If the sudoku contains a row or column of numbers in ascending or descending order, press the left button, otherwise, press the right button
    function isAscending(arr: number[]) {
      for (let i = 0; i < arr.length - 1; i++) {
        if (arr[i] > arr[i + 1]) return false;
      }
      return true;
    }

    for (let i = 0; i < 5; i++) {
      const row = sudoku.solution[i].map(Number);
      if (isAscending(row) || isAscending(row.reverse())) {
        return CampgroundControlsType.RED_BUTTON;
      }
    }

    // Check columns
    for (let j = 0; j < 5; j++) {
      const col = [];
      for (let i = 0; i < 5; i++) {
        col.push(Number(sudoku.solution[i][j]));
      }
      if (isAscending(col) || isAscending(col.reverse())) {
        return CampgroundControlsType.RED_BUTTON;
      }
    }

    return CampgroundControlsType.BLUE_BUTTON;
  },
  "☆ C": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => {
    // If there is a consonant on a surrounded 2, press the blue button, otherwise, press the right button
    const surrounded = getSurroundedCells(logic);
    for (const [i, j] of surrounded) {
      if (
        Number(sudoku.solution[i][j]) === 2 &&
        isConsonant(crossword.solution[i][j])
      ) {
        return CampgroundControlsType.BLUE_BUTTON;
      }
    }

    return CampgroundControlsType.GREEN_BUTTON;
  },
  "☆ D": (
    _id: number,
    _logic: GridPuzzleSpec,
    _crossword: CrosswordGridSpec,
    _sudoku: GridPuzzleSpec,
  ) =>
    // If the Logic grid has a unique solution, press the blue button, otherwise, press the green button
    // This one is a trick, they are all unique, but making them check is good
    CampgroundControlsType.BLUE_BUTTON,
  "☆ E": (
    id: number,
    logic: GridPuzzleSpec,
    crossword: CrosswordGridSpec,
    sudoku: GridPuzzleSpec,
  ) => {
    const isolated = getIsolatedCells(logic);
    // If an isolated letter in the last five letters of the alphabet is on a number divisible by two, press the right button, otherwise, press the middle button
    for (let i = 0; i < 5; i++) {
      for (let j = 0; j < 5; j++) {
        const isIsolated = isolated.some(
          (cell) => cell[0] === i && cell[1] === j,
        );
        const isLastFiveLetters = ["V", "W", "X", "Y", "Z"].includes(
          crossword.solution[i][j],
        );
        const isDivisibleByTwo = [2, 4].includes(Number(sudoku.solution[i][j]));
        if (isIsolated && isLastFiveLetters && isDivisibleByTwo) {
          return CampgroundControlsType.BLUE_BUTTON;
        }
      }
    }

    return CampgroundControlsType.GREEN_BUTTON;
  },
};

export class ElandIslandsGameScene extends BaseGameScene {
  #roomToHidingPlaces = new Map<number, HidingPlace[]>();
  #roomToSquirrels = new Map<number, Squirrel[]>();
  #hidingPlacesGroup!: Phaser.GameObjects.Group;
  #hidersGroup!: Phaser.GameObjects.Group;
  #buttons = new Map<
    CampgroundControlsType,
    CampgroundButton<CampgroundControlsType>
  >();
  #timer: CampgroundTimer | undefined;
  #manualIndexDisplay: CampgroundManualIndex | undefined;
  #map: Phaser.Tilemaps.Tilemap | undefined;
  #puzzles: GridPuzzle<GridPuzzleSpec>[] = [];
  #roundIndex = -1;
  #manualIndex = -1;
  #gameInProgress = false;
  #currentScore = 0;
  #highScore = 0;
  #prevHighScore = 0;
  #isPresser = false;

  constructor() {
    super(SCENE_KEYS.ELAND_ISLANDS_GAME_SCENE);
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (!map) {
      return;
    }

    // Initialize groups before creating objects
    if (!this.#hidingPlacesGroup) {
      this.#hidingPlacesGroup = this.add.group([]);
    }
    if (!this.#hidersGroup) {
      this.#hidersGroup = this.add.group([], {
        runChildUpdate: true,
      });
    }

    this.#map = map;

    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => {
        return {
          name: layerName,
          roomId: parseInt(layerName.split("/")[1], 10),
        };
      },
    );
    const controlsLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.CONTROLS}`),
    );
    controlsLayerNames.forEach((layer) => {
      this.#createButtons(map, layer.name, layer.roomId);
    });

    EVENT_BUS.addListener(CUSTOM_EVENTS.START_ELAND_ISLANDS_GAME, () => {
      if (IS_STATIC_SITE) {
        appendGameworldActivityEntry({
          type: "eland_islands_game_start",
          level: this.dataManager.data.currentArea.level,
          object_id: this.#roundIndex.toString(),
          frame: null,
        });
      } else {
        const client = newClient(apiUrl());
        client
          .elandIslandsGameStart({
            params: {
              level: this.dataManager.data.currentArea.level,
              roundId: this.#roundIndex.toString(),
            },
          })
          .catch((ex: unknown) => {
            console.error(ex);
          });
      }
      this.setFrontendFlag("eland_islands_game_in_progress", "true");
    });

    const hidingPlacesLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.HIDING_PLACES}`),
    );
    hidingPlacesLayerNames.forEach((layer) => {
      this.#createHidingPlaces(map, layer.name, layer.roomId);
    });

    return map;
  }

  private onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix: Phaser.Display.ColorMatrix =
        camera.postFX.addColorMatrix();

      colorMatrix.saturate(1.2);
      colorMatrix.contrast(0.2);

      const matrix = colorMatrix.getData();
      matrix[12] *= 1.15;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xccf0ff, 1.2, 0.2, false, 0.05, 8);
    }
  };

  protected override applyRoundGameworldState(level: string): void {
    super.applyRoundGameworldState(level);
    this.#setPrevHighScore();

    // If squirrel_rp is completed, disable squirrels.
    const squirrelRpFlag = this.dataManager.getFlagValue(
      STORY_FLAG.squirrel_rp,
    );
    if (squirrelRpFlag === "completed") {
      // Disable all squirrels in all rooms
      this.#roomToSquirrels.forEach((squirrels) => {
        squirrels.forEach((squirrel) => {
          squirrel.setPosition(0, 0);
          squirrel.disableObject();
        });
      });

      this.dataManager.setFlagToCompleted(STORY_FLAG.squirrel_location);
    }

    const levelState = this.gameworldStateData.levels.get(level);

    this.#currentScore = levelState?.elandIslandsCurrentScore ?? 0;
    this.#highScore = levelState?.elandIslandsHighScore ?? 0;

    this.scene.launch(SCENE_KEYS.ELAND_ISLANDS_SCORE_DISPLAY_SCENE, {
      currentScore: this.#currentScore,
      highScore: this.#highScore,
      visible: levelState?.elandIslandsGameInProgress ?? false,
    });

    if (
      levelState?.elandIslandsRoundIndex !== undefined &&
      levelState?.elandIslandsRoundIndex > -1
    ) {
      this.#roundIndex = levelState.elandIslandsRoundIndex;
    }

    if (
      levelState?.elandIslandsManualIndex !== undefined &&
      levelState?.elandIslandsManualIndex > -1
    ) {
      this.#manualIndex = levelState.elandIslandsManualIndex;
    }

    if (levelState?.elandIslandsGameInProgress) {
      this.#gameInProgress = true;
      this.renderPuzzles(this.#roundIndex);
      if (levelState.elandIslandsGameLastEventTime !== undefined) {
        this.#timer?.start(
          ELAND_ISLANDS_GAME_TIME_LIMIT_SECONDS -
            (new Date().getTime() -
              levelState.elandIslandsGameLastEventTime.getTime()) /
              1000,
        );
      }
      this.#buttons.forEach((button) => {
        button.activate();
        button.unPress();
      });
      this.dataManager.setFrontendFlag(
        "eland_islands_game_in_progress",
        "true",
      );
    }
  }

  protected override onInitRound(): void {
    this.setupLocalEventListeners();
  }

  private setupLocalEventListeners(): void {
    const onStart = (event: Event) => {
      this.onStart(
        (event as CustomEvent<ElandIslandsWindowEventDetail>).detail,
      );
    };

    const onFailure = (event: Event) => {
      this.onFailure(
        (event as CustomEvent<ElandIslandsWindowEventDetail>).detail,
      );
    };

    const onSuccess = (event: Event) => {
      this.onSuccess(
        (event as CustomEvent<ElandIslandsWindowEventDetail>).detail,
      );
    };

    window.addEventListener(ELAND_ISLANDS_WINDOW_EVENTS.START, onStart);
    window.addEventListener(ELAND_ISLANDS_WINDOW_EVENTS.SUCCESS, onSuccess);
    window.addEventListener(ELAND_ISLANDS_WINDOW_EVENTS.FAILURE, onFailure);
    EVENT_BUS.addListener(
      CUSTOM_EVENTS.START_SQUIRREL_CHASE,
      this.#handleStartSquirrelChase,
    );

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      window.removeEventListener(ELAND_ISLANDS_WINDOW_EVENTS.START, onStart);
      window.removeEventListener(
        ELAND_ISLANDS_WINDOW_EVENTS.FAILURE,
        onFailure,
      );
      window.removeEventListener(
        ELAND_ISLANDS_WINDOW_EVENTS.SUCCESS,
        onSuccess,
      );
      EVENT_BUS.removeListener(
        CUSTOM_EVENTS.START_SQUIRREL_CHASE,
        this.#handleStartSquirrelChase,
      );
    });
  }

  /**
   * Gets the position next to Burnham for the squirrel to spawn/restart
   */
  #getSquirrelPositionNextToBurnham():
    | Phaser.Types.Math.Vector2Like
    | undefined {
    const burnham = this.getCharacterByIdentifier("BURNHAM");
    if (!burnham) {
      return undefined;
    }
    return {
      x: burnham.x + burnham.width + 8, // offset so the squirrel isn't on top of Burnham
      y: burnham.y,
    };
  }

  #handleStartSquirrelChase = (): void => {
    const roomId = SQUIRREL_ROOM_ID;
    const squirrels = this.#roomToSquirrels.get(roomId);
    let squirrel = squirrels?.[0];

    // Create squirrel if it doesn't exist
    if (!squirrel) {
      this.dataManager.setFlagValue(STORY_FLAG.squirrel_location, "running");
      const hidingPlacesInRoom = this.#roomToHidingPlaces.get(roomId) || [];
      const squirrelPosition = this.#getSquirrelPositionNextToBurnham();

      squirrel = new Squirrel({
        scene: this,
        hidingPlaces: hidingPlacesInRoom,
        spawnPosition: squirrelPosition,
      });

      if (!this.#roomToSquirrels.has(roomId)) {
        this.#roomToSquirrels.set(roomId, []);
      }
      this.#roomToSquirrels.get(roomId)?.push(squirrel);
      this.#hidersGroup.add(squirrel);
      squirrel.restartObject();
    } else {
      this.dataManager.setFlagValue(STORY_FLAG.squirrel_location, "running");
      // Reposition squirrel next to Burnham
      const squirrelPosition = this.#getSquirrelPositionNextToBurnham();
      if (squirrelPosition) {
        squirrel.setPosition(squirrelPosition.x, squirrelPosition.y);
      }

      // Reset the squirrel's state and start the chase
      // This clears visited hiding places, resets found count, stops movement, etc.
      squirrel.restartObject();
    }
  };

  private onStart(detail: ElandIslandsWindowEventDetail): void {
    if (
      this.dataManager.data.currentArea.level !== detail.level ||
      this.playerObject.isDefeated
    ) {
      return;
    }

    this.#roundIndex += 1;
    this.#manualIndex += 1;
    this.#gameInProgress = true;
    this.resetCurrentScore();
    this.renderPuzzles(this.#roundIndex);
    this.#timer?.start(ELAND_ISLANDS_GAME_TIME_LIMIT_SECONDS);
    this.updateScoreUI(true);
    this.setFrontendFlag("eland_islands_game_in_progress", "true");
    this.#buttons.forEach((button) => {
      button.activate();
      button.unPress();
    });
  }

  private onFailure(detail: ElandIslandsWindowEventDetail): void {
    if (
      this.dataManager.data.currentArea.level !== detail.level ||
      this.playerObject.isDefeated
    ) {
      return;
    }

    this.resetGame();
  }

  private resetGame(): void {
    if (this.#highScore > this.#prevHighScore && this.#isPresser) {
      const interactionId = `eland_islands${this.#highScore.toString().padStart(2, "0")}`;
      this.dataManager.setFlagToCompleted(interactionId);
      this.#prevHighScore = this.#highScore;
    }
    this.#isPresser = false;
    this.#gameInProgress = false;
    this.resetCurrentScore();
    this.clearPuzzles();
    this.updateScoreUI(false);
    this.#timer?.clear();
    this.#manualIndexDisplay?.setText("");
    this.setFrontendFlag("eland_islands_game_in_progress", "false");
    this.#buttons.forEach((button) => {
      button.press();
      button.deactivate();
    });
  }

  private onSuccess(detail: ElandIslandsWindowEventDetail): void {
    if (
      this.dataManager.data.currentArea.level !== detail.level ||
      this.playerObject.isDefeated
    ) {
      return;
    }

    // To avoid multiple people completing the interaction, we only complete the interaction
    // on the client that pushed the button, and the other clients just increment the current
    // score for tracking.
    this.incrementCurrentScore();
    this.#manualIndex += 1;
    this.renderPuzzles(this.#roundIndex);
    this.updateScoreUI(true);

    if (this.#currentScore === MAX_SCORE) {
      this.playerObject.animationComponent.playAnimation(
        CHARACTER_ANIMATIONS.WAVE,
        () => {
          this.playerObject.animationComponent.playAnimation(
            CHARACTER_ANIMATIONS.IDLE_DOWN,
          );
        },
      );
      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["Congratulations! You completed all levels of Puzzathlon!"],
        choices: [],
      });
      this.resetGame();
    }
  }

  private onTimeout(): void {
    this.resetGame();
  }

  private onButtonPress(controlType: CampgroundControlsType): boolean {
    this.#isPresser = true;

    if (!this.#gameInProgress) {
      return false;
    }

    const logicGrids = (
      this.cache.json.get(ASSET_KEYS.GRID_LOGIC) as {
        grids: GridPuzzleSpec[];
      }
    ).grids;
    const logic = logicGrids[this.#roundIndex % logicGrids.length];

    const crosswordGrids = (
      this.cache.json.get(ASSET_KEYS.CROSSWORDS) as {
        grids: CrosswordGridSpec[];
      }
    ).grids;
    const crossword = crosswordGrids[this.#roundIndex % crosswordGrids.length];

    const sudokuGrids = (
      this.cache.json.get(ASSET_KEYS.SUDOKU) as {
        grids: GridPuzzleSpec[];
      }
    ).grids;
    const sudoku = sudokuGrids[this.#roundIndex % sudokuGrids.length];

    const correctButton = MANUAL[
      getManualEntry(this.#currentScore, this.#manualIndex)
    ](this.#roundIndex, logic, crossword, sudoku);

    if (controlType === correctButton) {
      if (IS_STATIC_SITE) {
        appendGameworldActivityEntry({
          type: "eland_islands_game_success",
          level: this.dataManager.data.currentArea.level,
          object_id: this.#roundIndex.toString(),
          frame: null,
        });
        if (this.#currentScore + 1 > this.#highScore) {
          recordInteractionCompleted(
            `r8pd${(this.#currentScore + 1).toString().padStart(2, "0")}`,
          );
        }
      } else {
        const client = newClient(apiUrl());
        retryClientCall(() =>
          client.elandIslandsGameSuccess({
            params: {
              level: this.dataManager.data.currentArea.level,
              roundId: this.#roundIndex.toString(),
            },
          }),
        ).catch((err: unknown) => {
          console.error(err);
        });

        if (this.#currentScore + 1 > this.#highScore) {
          retryClientCall(() =>
            client.completeInteraction({
              params: {
                interactionId: `r8pd${(this.#currentScore + 1).toString().padStart(2, "0")}`,
              },
            }),
          ).catch((err: unknown) => {
            console.error(err);
          });
        }
      }
      return true;
    } else {
      if (IS_STATIC_SITE) {
        appendGameworldActivityEntry({
          type: "eland_islands_game_failure",
          level: this.dataManager.data.currentArea.level,
          object_id: this.#roundIndex.toString(),
          frame: null,
        });
      } else {
        const client = newClient(apiUrl());
        client
          .elandIslandsGameFailed({
            params: {
              level: this.dataManager.data.currentArea.level,
              roundId: this.#roundIndex.toString(),
            },
          })
          .catch((err: unknown) => {
            console.error(err);
          });
      }
      return false;
    }
  }

  private renderPuzzles(index: number): void {
    this.#manualIndexDisplay?.setText(
      getManualEntry(this.#currentScore, this.#manualIndex),
    );

    // Calculate and display correct answer in debug mode
    if (ENABLE_DEBUG) {
      if (this.#gameInProgress) {
        const logicGrids = (
          this.cache.json.get(ASSET_KEYS.GRID_LOGIC) as {
            grids: GridPuzzleSpec[];
          }
        ).grids;
        const logic = logicGrids[index % logicGrids.length];

        const crosswordGrids = (
          this.cache.json.get(ASSET_KEYS.CROSSWORDS) as {
            grids: CrosswordGridSpec[];
          }
        ).grids;
        const crossword = crosswordGrids[index % crosswordGrids.length];

        const sudokuGrids = (
          this.cache.json.get(ASSET_KEYS.SUDOKU) as {
            grids: GridPuzzleSpec[];
          }
        ).grids;
        const sudoku = sudokuGrids[index % sudokuGrids.length];

        const correctButton = MANUAL[
          getManualEntry(this.#currentScore, this.#manualIndex)
        ](index, logic, crossword, sudoku);

        logger.info(`correctButton: ${correctButton}`);
      }
    }

    if (!this.#map) {
      console.error("expected map to be defined but it wasn't");
      return;
    }

    const dynamicInjectionsLayer = this.#map
      .getObjectLayerNames()
      .find((name) => name.endsWith(TILED_LAYER_NAMES.DYNAMIC_INJECTIONS));
    if (dynamicInjectionsLayer === undefined) {
      return;
    }

    this.clearPuzzles();

    const dynamicInjections = getTiledDynamicInjectionObjectsFromMap(
      this.#map,
      dynamicInjectionsLayer,
    );
    dynamicInjections.forEach((object) => {
      let Class: typeof GridPuzzle<GridPuzzleSpec>;
      let asset: GridPuzzleSpec;
      if (object.injectionType === DYNAMIC_INJECTION_TYPE.GRID_LOGIC) {
        const grids = (
          this.cache.json.get(ASSET_KEYS.GRID_LOGIC) as {
            grids: GridPuzzleSpec[];
          }
        ).grids;
        asset = grids[index % grids.length];
        if (asset.puzzleType === GridPuzzleType.SLITHERLINK) {
          Class = Slitherlink;
        } else if (asset.puzzleType === GridPuzzleType.NURIKABE) {
          Class = Nurikabe;
        } else if (asset.puzzleType === GridPuzzleType.YAJILIN) {
          Class = Yajilin;
        } else {
          throw new Error(`Bug: invalid puzzle type ${asset.puzzleType}`);
        }
      } else if (object.injectionType === DYNAMIC_INJECTION_TYPE.CROSSWORD) {
        const grids = (
          this.cache.json.get(ASSET_KEYS.CROSSWORDS) as {
            grids: CrosswordGridSpec[];
          }
        ).grids;
        asset = grids[index % grids.length];
        if (asset.puzzleType === GridPuzzleType.BARRED_CROSSWORD) {
          Class = BarredCrossword;
        } else if (asset.puzzleType === GridPuzzleType.BLOCKED_CROSSWORD) {
          Class = BlockedCrossword;
        } else {
          throw new Error(`Bug: invalid puzzle type ${asset.puzzleType}`);
        }
      } else if (object.injectionType === DYNAMIC_INJECTION_TYPE.SUDOKU) {
        const grids = (
          this.cache.json.get(ASSET_KEYS.SUDOKU) as {
            grids: GridPuzzleSpec[];
          }
        ).grids;
        asset = grids[index % grids.length];
        if (asset.puzzleType === GridPuzzleType.JIGSAW_SUDOKU) {
          Class = JigsawSudoku;
        } else if (asset.puzzleType === GridPuzzleType.THERMO_SUDOKU) {
          Class = ThermoSudoku;
        } else if (asset.puzzleType === GridPuzzleType.KILLER_SUDOKU) {
          Class = KillerSudoku;
        } else {
          throw new Error(`Bug: invalid puzzle type ${asset.puzzleType}`);
        }
      } else {
        console.log("this type isn't handled yet");
        return;
      }

      const puzzle = new Class(this, object, asset);
      this.add.existing(puzzle);
      puzzle.enableObject();
      this.#puzzles.push(puzzle);
    });
  }

  #createButtons(
    map: Phaser.Tilemaps.Tilemap,
    layerName: string,
    _roomId: number,
  ): void {
    const validTiledObjects =
      getTiledControlsObjectsFromMap<CampgroundControlsType>(map, layerName);
    validTiledObjects.forEach((object) => {
      if (
        object.controlType === CampgroundControlsType.RED_BUTTON ||
        object.controlType === CampgroundControlsType.GREEN_BUTTON ||
        object.controlType === CampgroundControlsType.BLUE_BUTTON
      ) {
        const button = new CampgroundButton<CampgroundControlsType>(
          this,
          object,
          (controlType) => {
            return this.onButtonPress(controlType);
          },
        );
        this.#buttons.set(object.controlType, button);
      } else if (object.controlType === CampgroundControlsType.TIMER) {
        this.#timer = new CampgroundTimer(this, object, () => {
          this.onTimeout();
        });
      } else if (object.controlType === CampgroundControlsType.MANUAL_INDEX) {
        this.#manualIndexDisplay = new CampgroundManualIndex(this, object);
      }
    });
  }

  #createHidingPlaces(
    map: Phaser.Tilemaps.Tilemap,
    layerName: string,
    roomId: number,
  ): void {
    const validTiledObjects = getTiledHidingPlaceObjectsFromMap(map, layerName);
    validTiledObjects.forEach((object) => {
      const hidingPlace = new HidingPlace(this, object);
      if (!this.#roomToHidingPlaces.has(roomId)) {
        this.#roomToHidingPlaces.set(roomId, []);
      }
      this.#roomToHidingPlaces.get(roomId)?.push(hidingPlace);
      this.#hidingPlacesGroup.add(hidingPlace);
    });
  }

  protected override registerRoundEvents(): void {
    super.registerRoundEvents();

    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
  }

  /**
   * Registers collision detection between hiders (squirrels) and hiding places
   */
  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Register a single overlap between hiders group and hiding places group
    this.physics.add.overlap(
      this.#hidersGroup,
      this.#hidingPlacesGroup,
      (hiderObj, hidingPlaceObj) => {
        // Get the hiding component from the object
        const hidingComponent = HidingComponent.getComponent<HidingComponent>(
          hiderObj as GameObject,
        );
        if (!hidingComponent) {
          return;
        }

        const hidingPlace = hidingPlaceObj as HidingPlace;

        // Check if this hiding place is the component's target
        if (hidingComponent.isTargetHidingPlace(hidingPlace)) {
          hidingPlace.registerHidingEntity(hidingComponent);
          hidingComponent.hideInHidingPlace(hidingPlace);
          this.refreshLevelObjects();
        }
      },
      undefined,
      this,
    );
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);
    this.#buttons.forEach((button) => {
      button.enableObject();
    });
    this.#timer?.enableObject();
    this.#manualIndexDisplay?.enableObject();
    this.#roomToHidingPlaces.get(roomId)?.forEach((hidingPlace) => {
      hidingPlace.enableObject();
    });
    this.#roomToSquirrels.get(roomId)?.forEach((squirrel) => {
      squirrel.enableObject();
    });
  }

  protected override disableRoomObjects(roomId: number): void {
    super.disableRoomObjects(roomId);
    this.#buttons.forEach((button) => {
      button.disableObject();
    });
    this.#timer?.disableObject();
    this.#manualIndexDisplay?.disableObject();
    this.#roomToHidingPlaces.get(roomId)?.forEach((hidingPlace) => {
      hidingPlace.disableObject();
    });
    this.#roomToSquirrels.get(roomId)?.forEach((squirrel) => {
      squirrel.disableObject();
    });
  }

  protected appendRoomInteractiveObjects(
    roomId: number,
    objects: InteractiveGameObject[],
  ): void {
    this.#buttons.forEach((button) => objects.push(button));
    this.#roomToHidingPlaces
      .get(roomId)
      ?.forEach((hidingPlace) => objects.push(hidingPlace));
  }

  private clearPuzzles(): void {
    this.#puzzles.forEach((puzzle) => {
      puzzle.destroy();
    });
    this.#puzzles = [];
  }

  private resetCurrentScore(): void {
    this.#currentScore = 0;
  }

  private incrementCurrentScore(): void {
    this.#currentScore += 1;
    this.#highScore = Math.max(this.#highScore, this.#currentScore);
  }

  protected override refreshLevelObjects(): void {
    // Call parent to handle base refresh logic
    super.refreshLevelObjects();

    // Check if squirrel should restart
    const squirrelFlagValue = this.dataManager.getFlagValue(
      STORY_FLAG.squirrel_location,
    );
    if (squirrelFlagValue === "restart") {
      // Get all squirrels in the current room
      const currentRoomId = this.currentRoomId;
      const squirrels = this.#roomToSquirrels.get(currentRoomId);

      if (squirrels && squirrels.length > 0) {
        // Get the first squirrel (there should only be one in room 1)
        const squirrel = squirrels[0];

        // Move squirrel to player position
        squirrel.setPosition(this.playerObject.x, this.playerObject.y);

        // Restart the squirrel's sequence
        squirrel.restartObject();
      }
    }
  }

  private updateScoreUI(gameInProgress: boolean): void {
    EVENT_BUS.emit(CUSTOM_EVENTS.ELAND_ISLANDS_GAME_UPDATE, {
      currentScore: this.#currentScore,
      highScore: this.#highScore,
      visible: gameInProgress,
    });
  }

  #setPrevHighScore(): void {
    // Determine the previous high score based on completed interactions
    let prevHighScore = 0;
    for (let score = 1; score <= MAX_SCORE; score++) {
      const interactionId = `eland_islands${score.toString().padStart(2, "0")}`;
      const isCompleted =
        this.dataManager.getFlagValue(interactionId) === "completed";
      if (isCompleted) {
        prevHighScore = score;
      } else {
        break;
      }
    }
    this.#prevHighScore = prevHighScore;
  }
}
