import * as Phaser from "phaser";
import { LINE_COLOR_STRING } from "../../../common/eland-islands";
import type {
  CampgroundControlsType,
  TiledControlsObject,
} from "../../../common/tiled/types";
import { CampgroundDisplay } from "./display";

export class CampgroundManualIndex extends CampgroundDisplay {
  #text: Phaser.GameObjects.Text;

  constructor(
    scene: Phaser.Scene,
    config: TiledControlsObject<CampgroundControlsType>,
  ) {
    super(scene, config);

    this.#text = new Phaser.GameObjects.Text(this.scene, 0, 0, "", {
      color: LINE_COLOR_STRING,
      align: "center",
      fontSize: 11,
      fontFamily: "Arial",
    });
    this.setContents(this.#text);
    this.disableObject();
  }

  public setText(text: string): void {
    this.#text.setText(text);
    this.recenter();
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
  }
}
