import * as Phaser from "phaser";
import { LINE_COLOR_INT } from "../../common/eland-islands";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { GridPuzzle, type GridPuzzleSpec } from "./grid_puzzle";

const STEM_WIDTH = 6;

type ThermoSudokuSpec = GridPuzzleSpec & {
  // List of thermometers, where each thermometer is represented as a list of x, y coordinates.
  // Each coordinate is either the start or end of the thermometer, or a point where the stem
  // bends.
  thermometers: number[][][];
};

export class ThermoSudoku extends GridPuzzle<ThermoSudokuSpec> {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: ThermoSudokuSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();

    this.add(this.makeGrid());
    this.add(this.makeNumbers());
    this.add(this.makeBars());
    this.add(this.renderThermometers());
  }

  private renderThermometers(): Phaser.GameObjects.GameObject[] {
    return this.asset.thermometers.map((thermometer) =>
      this.renderThermometer(thermometer),
    );
  }

  private renderThermometer(
    thermometer: number[][],
  ): Phaser.GameObjects.Graphics {
    const graphics = new Phaser.GameObjects.Graphics(this.scene, {
      fillStyle: { color: LINE_COLOR_INT },
      x: 0,
      y: 0,
    });

    const start = thermometer[0];
    const startCoord = this.cellCoord(start[0], start[1]);
    graphics.fillCircle(
      startCoord.x + startCoord.width / 2,
      startCoord.y + startCoord.height / 2,
      6,
    );
    for (let i = 0; i < thermometer.length - 1; i++) {
      const cell1Coord = this.cellCoord(thermometer[i][0], thermometer[i][1]);
      const cell2Coord = this.cellCoord(
        thermometer[i + 1][0],
        thermometer[i + 1][1],
      );

      const cell1Center = {
        x: cell1Coord.x + cell1Coord.width / 2,
        y: cell1Coord.y + cell1Coord.height / 2,
      };
      const cell2Center = {
        x: cell2Coord.x + cell2Coord.width / 2,
        y: cell2Coord.y + cell2Coord.height / 2,
      };

      this.drawThermometerStem(cell1Center, cell2Center, graphics);
    }

    return graphics;
  }

  private drawThermometerStem(
    cell1Center: { x: number; y: number },
    cell2Center: { x: number; y: number },
    graphics: Phaser.GameObjects.Graphics,
  ): void {
    const overshoot = STEM_WIDTH / 2 - 1.5;
    if (cell1Center.x === cell2Center.x) {
      graphics.fillRect(
        cell1Center.x - STEM_WIDTH / 2,
        Math.min(cell1Center.y, cell2Center.y) - overshoot,
        STEM_WIDTH,
        Math.abs(cell1Center.y - cell2Center.y) + overshoot * 2,
      );
    } else if (cell1Center.y === cell2Center.y) {
      graphics.fillRect(
        Math.min(cell1Center.x, cell2Center.x) - overshoot,
        cell1Center.y - STEM_WIDTH / 2,
        Math.abs(cell1Center.x - cell2Center.x) + overshoot * 2,
        STEM_WIDTH,
      );
    } else if (
      (cell2Center.y - cell1Center.y) / (cell1Center.x - cell2Center.x) >
      0
    ) {
      const lower = cell1Center.x < cell2Center.x ? cell2Center : cell1Center;
      const upper = cell1Center.x < cell2Center.x ? cell1Center : cell2Center;

      const offset1 = new Phaser.Math.Vector2(-1, 1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(1, 1).normalize().scale(STEM_WIDTH / 2));
      const offset2 = new Phaser.Math.Vector2(-1, 1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(-1, -1).normalize().scale(STEM_WIDTH / 2));
      const offset3 = new Phaser.Math.Vector2(1, -1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(-1, -1).normalize().scale(STEM_WIDTH / 2));
      const offset4 = new Phaser.Math.Vector2(1, -1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(1, 1).normalize().scale(STEM_WIDTH / 2));

      graphics.fillPoints(
        [
          new Phaser.Geom.Point(upper.x + offset1.x, upper.y + offset1.y),
          new Phaser.Geom.Point(upper.x + offset2.x, upper.y + offset2.y),
          new Phaser.Geom.Point(lower.x + offset3.x, lower.y + offset3.y),
          new Phaser.Geom.Point(lower.x + offset4.x, lower.y + offset4.y),
        ],
        true,
        true,
      );
    } else {
      const lower = cell1Center.x < cell2Center.x ? cell2Center : cell1Center;
      const upper = cell1Center.x < cell2Center.x ? cell1Center : cell2Center;

      const offset1 = new Phaser.Math.Vector2(-1, -1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(-1, 1).normalize().scale(STEM_WIDTH / 2));
      const offset2 = new Phaser.Math.Vector2(-1, -1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(1, -1).normalize().scale(STEM_WIDTH / 2));
      const offset3 = new Phaser.Math.Vector2(1, 1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(1, -1).normalize().scale(STEM_WIDTH / 2));
      const offset4 = new Phaser.Math.Vector2(1, 1)
        .normalize()
        .scale(overshoot)
        .add(new Phaser.Math.Vector2(-1, 1).normalize().scale(STEM_WIDTH / 2));

      graphics.fillPoints(
        [
          new Phaser.Geom.Point(upper.x + offset1.x, upper.y + offset1.y),
          new Phaser.Geom.Point(upper.x + offset2.x, upper.y + offset2.y),
          new Phaser.Geom.Point(lower.x + offset3.x, lower.y + offset3.y),
          new Phaser.Geom.Point(lower.x + offset4.x, lower.y + offset4.y),
        ],
        true,
        true,
      );
    }
  }
}
