import * as Phaser from "phaser";
import { LINE_COLOR_STRING } from "../../../common/eland-islands";
import type {
  CampgroundControlsType,
  TiledControlsObject,
} from "../../../common/tiled/types";
import { CampgroundDisplay } from "./display";

export class CampgroundTimer extends CampgroundDisplay {
  private interval: ReturnType<typeof setInterval> | undefined;
  private text: Phaser.GameObjects.Text;
  private onTimeout: () => void;

  constructor(
    scene: Phaser.Scene,
    config: TiledControlsObject<CampgroundControlsType>,
    onTimeout: () => void,
  ) {
    super(scene, config);
    this.onTimeout = onTimeout;
    this.disableObject();

    this.scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      clearInterval(this.interval);
      this.interval = undefined;
    });

    this.text = new Phaser.GameObjects.Text(this.scene, 0, 0, "", {
      color: LINE_COLOR_STRING,
      align: "center",
      fontSize: 12,
      fontFamily: "Arial",
    });
    this.setContents(this.text);
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
  }

  public start(timeSeconds: number): void {
    if (this.interval !== undefined) {
      clearInterval(this.interval);
      this.interval = undefined;
    }

    let last = new Date();
    this.interval = setInterval(() => {
      timeSeconds -= (new Date().getTime() - last.getTime()) / 1000;
      last = new Date();
      this.setText(this.formatTime(Math.ceil(timeSeconds)));
      if (timeSeconds <= 0) {
        this.onTimeout();
        clearInterval(this.interval);
        this.interval = undefined;
        this.setText("");
      }
    }, 100);
  }

  public clear(): void {
    clearInterval(this.interval);
    this.interval = undefined;
    this.setText("");
  }

  private setText(text: string): void {
    this.text.setText(text);
    this.recenter();
  }

  private formatTime(timeSeconds: number): string {
    return `${Math.floor(timeSeconds / 60)
      .toString()
      .padStart(
        2,
        "0",
      )}:${(Math.ceil(timeSeconds) % 60).toString().padStart(2, "0")}`;
  }
}
