import * as Phaser from "phaser";
import { LINE_COLOR_INT } from "../../common/eland-islands";
import { type TiledDynamicInjectionObject } from "../../common/tiled/types";
import { GridPuzzle, type GridPuzzleSpec } from "./grid_puzzle";

const OFFSET = 3;
const DASH_LENGTH = 3;
const GAP_LENGTH = 1;

type KillerSudokuSpec = GridPuzzleSpec & {
  cages: { cells: number[][]; value: number }[];
};

export class KillerSudoku extends GridPuzzle<KillerSudokuSpec> {
  constructor(
    scene: Phaser.Scene,
    tiledObject: TiledDynamicInjectionObject,
    asset: KillerSudokuSpec,
  ) {
    super(scene, tiledObject, asset);

    this.disableObject();

    this.add(this.makeGrid());
    this.add(this.makeNumbers());
    this.add(this.makeBars());
    this.add(this.makeCages());
    this.add(this.makeCageValues());
  }

  private makeCages() {
    const graphics = new Phaser.GameObjects.Graphics(this.scene);
    graphics.lineStyle(1, LINE_COLOR_INT, 1);

    this.asset.cages.forEach((cage) => {
      // Create a set of cells in this cage for quick lookup
      const cageSet = new Set(cage.cells.map(([row, col]) => `${row},${col}`));

      // For each cell in the cage, check which edges need dotted lines
      cage.cells.forEach(([row, col]) => {
        const coord = this.cellCoord(row, col);

        // Check top edge
        if (!cageSet.has(`${row - 1},${col}`)) {
          const y = coord.y + OFFSET;
          this.drawDottedLine(
            graphics,
            coord.x + (cageSet.has(`${row},${col - 1}`) ? 0 : OFFSET),
            y,
            coord.x +
              coord.width -
              (cageSet.has(`${row},${col + 1}`) ? 0 : OFFSET),
            y,
            DASH_LENGTH,
            GAP_LENGTH,
          );
        }

        // Check bottom edge
        if (!cageSet.has(`${row + 1},${col}`)) {
          const y = coord.y + coord.height - OFFSET;
          this.drawDottedLine(
            graphics,
            coord.x + (cageSet.has(`${row},${col - 1}`) ? 0 : OFFSET),
            y,
            coord.x +
              coord.width -
              (cageSet.has(`${row},${col + 1}`) ? 0 : OFFSET),
            y,
            DASH_LENGTH,
            GAP_LENGTH,
          );
        }

        // Check left edge
        if (!cageSet.has(`${row},${col - 1}`)) {
          const x = coord.x + OFFSET;
          this.drawDottedLine(
            graphics,
            x,
            coord.y + (cageSet.has(`${row - 1},${col}`) ? 0 : OFFSET),
            x,
            coord.y +
              coord.height -
              (cageSet.has(`${row + 1},${col}`) ? 0 : OFFSET),
            DASH_LENGTH,
            GAP_LENGTH,
          );
        }

        // Check right edge
        if (!cageSet.has(`${row},${col + 1}`)) {
          const x = coord.x + coord.width - OFFSET;
          this.drawDottedLine(
            graphics,
            x,
            coord.y + (cageSet.has(`${row - 1},${col}`) ? 0 : OFFSET),
            x,
            coord.y +
              coord.height -
              (cageSet.has(`${row + 1},${col}`) ? 0 : OFFSET),
            DASH_LENGTH,
            GAP_LENGTH,
          );
        }
      });
    });

    return graphics;
  }

  private drawDottedLine(
    graphics: Phaser.GameObjects.Graphics,
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    dashLength: number,
    gapLength: number,
  ) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const lineLength = Math.sqrt(dx * dx + dy * dy);
    const segmentLength = dashLength + gapLength;
    const numSegments = Math.ceil(lineLength / segmentLength);

    const unitX = dx / lineLength;
    const unitY = dy / lineLength;

    for (let i = 0; i < numSegments; i++) {
      const startDist = i * segmentLength;
      const endDist = Math.min(startDist + dashLength, lineLength);

      if (startDist >= lineLength) break;

      const startX = x1 + unitX * startDist;
      const startY = y1 + unitY * startDist;
      const endX = x1 + unitX * endDist;
      const endY = y1 + unitY * endDist;

      graphics.lineBetween(startX, startY, endX, endY);
    }
  }

  private makeCageValues(): Phaser.GameObjects.Text[] {
    return this.asset.cages.map((cage) => {
      const minX = Math.min(...cage.cells.map((cell) => cell[0]));
      const topLeftY = Math.min(
        ...cage.cells.filter((cell) => cell[0] === minX).map((cell) => cell[1]),
      );

      const coord = this.cellCoord(minX, topLeftY);
      const rectangle = new Phaser.GameObjects.Rectangle(
        this.scene,
        coord.x + coord.width / 2,
        coord.y + coord.height / 2,
        this.object.width / this.dim,
        this.object.height / this.dim,
        LINE_COLOR_INT,
      );

      const text = this.makeText(coord, cage.value.toString(), 10);
      Phaser.Display.Align.In.TopLeft(text, rectangle, -5, -3);
      return text;
    });
  }
}
