import { ElandIslandsGameScene } from "../scenes/eland-islands-game-scene";
import { ElandIslandsPreloadScene } from "../scenes/eland-islands-preload-scene";
import { ElandIslandsScoreDisplay } from "../scenes/eland-islands-score-display";
import { GameOverScene } from "../scenes/game-over-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadElandIslandsScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.ELAND_ISLANDS_PRELOAD_SCENE,
    ElandIslandsPreloadScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.ELAND_ISLANDS_GAME_SCENE,
    ElandIslandsGameScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.ELAND_ISLANDS_SCORE_DISPLAY_SCENE,
    ElandIslandsScoreDisplay,
    false,
  );
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.start(SCENE_KEYS.ELAND_ISLANDS_PRELOAD_SCENE);
};
