import * as Phaser from "phaser";
import MANUAL_PDF from "../assets/puzzathlon.pdf";
import { ASSET_KEYS } from "../common/assets";
import { MAX_SCORE } from "../common/eland-islands";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { SCENE_KEYS } from "./scene-keys";

type Data = {
  currentScore: number;
  highScore: number;
  visible: boolean;
};

export class ElandIslandsScoreDisplay extends Phaser.Scene {
  #initialized = false;
  #currentScore: number | undefined;
  #highScore: number | undefined;
  #visible: boolean | undefined;
  #container: Phaser.GameObjects.Container | undefined;
  #dots: Phaser.GameObjects.Image[] = [];

  constructor() {
    super({
      key: SCENE_KEYS.ELAND_ISLANDS_SCORE_DISPLAY_SCENE,
    });
  }

  public init(data: Data): void {
    this.#currentScore = data.currentScore;
    this.#highScore = data.highScore;
    this.#visible = data.visible;

    EVENT_BUS.on(CUSTOM_EVENTS.ELAND_ISLANDS_GAME_UPDATE, (data: Data) => {
      this.#currentScore = data.currentScore;
      this.#highScore = data.highScore;
      this.#visible = data.visible;

      if (this.#initialized) {
        this.updateDisplay();
      }
    });
  }

  public create(): void {
    const centerHorizontally = this.cameras.main.displayWidth / 2;

    this.#container = new Phaser.GameObjects.Container(this, 0, 0);
    this.#container.setVisible(this.#visible ?? false);

    for (let i = 0; i < MAX_SCORE; i++) {
      const image = new Phaser.GameObjects.Image(
        this,
        centerHorizontally + (i - MAX_SCORE / 2) * 20,
        20,
        this.getImage(i),
        // In the main game scene we zoom the camera by 2x, but that does annoying things to coordinates here.
        // To simulate the same effect, we scale up the assets by 2x.
      ).setScale(2, 2);
      this.#container.add(image);
      this.#dots.push(image);
    }

    const paperIcon = new Phaser.GameObjects.Image(
      this,
      this.cameras.main.width - 30,
      this.cameras.main.height - 36,
      ASSET_KEYS.PAPER_ICON,
    )
      .setInteractive({ useHandCursor: true })
      .on("pointerdown", (): void => {
        window.open(MANUAL_PDF, "_blank", "noopener,noreferrer");
      })
      .setScale(3, 3);
    this.#container.add(paperIcon);

    this.add.existing(this.#container);
    this.#initialized = true;
  }

  private getImage(index: number): string {
    if ((this.#highScore ?? 0) < index + 1) {
      return ASSET_KEYS.SCORE_DOT_EMPTY;
    } else if ((this.#currentScore ?? 0) < index + 1) {
      return ASSET_KEYS.SCORE_DOT_FILLED;
    } else {
      return ASSET_KEYS.SCORE_DOT_BLACK_BORDER;
    }
  }

  private updateDisplay(): void {
    this.#container?.setVisible(this.#visible ?? false);

    this.#dots.forEach((dot, i) => {
      if ((this.#highScore ?? 0) < i + 1) {
        dot.setTexture(ASSET_KEYS.SCORE_DOT_EMPTY);
      } else if ((this.#currentScore ?? 0) < i + 1) {
        dot.setTexture(ASSET_KEYS.SCORE_DOT_FILLED);
      } else {
        dot.setTexture(ASSET_KEYS.SCORE_DOT_BLACK_BORDER);
      }
    });
  }
}
