import { type GameworldActivityLogEntry } from "@hunt/public-client";
import { useEffect, useMemo, useState } from "react";
import {
  ELAND_ISLANDS_WINDOW_EVENTS,
  type ElandIslandsWindowEventDetail,
} from "../../rounds/overworld/gameworld/common/eland-islands";
import {
  CUSTOM_EVENTS,
  EVENT_BUS,
} from "../../rounds/overworld/gameworld/common/event-bus";
import { useGameworldActivityLog } from "../../rounds/overworld/gameworld/gameworldLocalState";

const ELAND_ISLANDS_EVENT_TYPES: GameworldActivityLogEntry["type"][] = [
  "eland_islands_game_start",
  "eland_islands_game_failure",
  "eland_islands_game_success",
];

const ElandIslandsGameManager = (): null => {
  const [isSceneReady, setIsSceneReady] = useState<boolean>(false);
  const [pendingEvents, setPendingEvents] = useState<
    GameworldActivityLogEntry[]
  >([]);
  const events = useGameworldActivityLog(undefined, ELAND_ISLANDS_EVENT_TYPES);
  const [lastProcessedId, setLastProcessedId] = useState<number>(0);

  const eventIds = useMemo(() => events.map((event) => event.id), [events]);

  useEffect(() => {
    if (events.length === 0) {
      return;
    }

    if (lastProcessedId === 0) {
      setLastProcessedId(Math.max(0, ...eventIds));
      return;
    }

    const newEvents = events.filter((event) => event.id > lastProcessedId);
    if (newEvents.length === 0) {
      return;
    }

    const sortedEvents = [...newEvents].sort((a, b) => a.id - b.id);

    setPendingEvents((prev) => {
      const merged = [...prev];
      sortedEvents.forEach((event) => {
        if (!merged.some((existing) => existing.id === event.id)) {
          merged.push(event);
        }
      });
      merged.sort((a, b) => a.id - b.id);
      return merged;
    });

    setLastProcessedId((prev) =>
      Math.max(prev, ...sortedEvents.map((event) => event.id)),
    );
  }, [eventIds, events, lastProcessedId]);

  useEffect(() => {
    if (!isSceneReady || pendingEvents.length === 0) {
      return;
    }

    pendingEvents.forEach((event) => {
      const detail: ElandIslandsWindowEventDetail = {
        level: event.level,
      };

      let eventName: string;
      if (event.type === "eland_islands_game_start") {
        eventName = ELAND_ISLANDS_WINDOW_EVENTS.START;
      } else if (event.type === "eland_islands_game_failure") {
        eventName = ELAND_ISLANDS_WINDOW_EVENTS.FAILURE;
      } else if (event.type === "eland_islands_game_success") {
        eventName = ELAND_ISLANDS_WINDOW_EVENTS.SUCCESS;
      } else {
        throw new Error(`invalid event name ${event.type}`);
      }

      window.dispatchEvent(new CustomEvent(eventName, { detail }));
    });

    setPendingEvents([]);
  }, [isSceneReady, pendingEvents]);

  useEffect(() => {
    const handleGameReady = () => {
      setIsSceneReady(true);
    };

    EVENT_BUS.on(CUSTOM_EVENTS.CURRENT_SCENE_READY, handleGameReady);

    return () => {
      EVENT_BUS.removeListener(
        CUSTOM_EVENTS.CURRENT_SCENE_READY,
        handleGameReady,
      );
    };
  }, []);

  return null;
};

export default ElandIslandsGameManager;
