import * as Phaser from "phaser";
import { LINE_COLOR_INT } from "../../../common/eland-islands";
import type {
  CampgroundControlsType,
  TiledControlsObject,
} from "../../../common/tiled/types";
import type { CustomObject } from "../../../common/types";

export class CampgroundDisplay
  extends Phaser.GameObjects.Container
  implements CustomObject
{
  #area: Phaser.GameObjects.Rectangle;
  #obj: Phaser.GameObjects.GameObject | undefined;

  constructor(
    scene: Phaser.Scene,
    config: TiledControlsObject<CampgroundControlsType>,
  ) {
    super(scene, config.x, config.y);

    const graphics = new Phaser.GameObjects.Graphics(this.scene, {
      lineStyle: {
        color: LINE_COLOR_INT,
        width: 1,
      },
    });
    graphics.strokeRect(0, 0, config.width, config.height);
    this.add(graphics);
    this.scene.add.existing(this);

    this.#area = new Phaser.GameObjects.Rectangle(
      this.scene,
      config.width / 2,
      config.height / 2,
      config.width,
      config.height,
    );

    this.setToBack();
  }

  public setContents(obj: Phaser.GameObjects.GameObject): void {
    // Realign the text in case it changed width.
    if (this.#obj !== undefined) {
      this.remove(this.#obj);
    }
    this.#obj = obj;
    Phaser.Display.Align.In.Center(this.#obj, this.#area);
    this.add(obj);
  }

  public recenter(): void {
    if (this.#obj !== undefined) {
      Phaser.Display.Align.In.Center(this.#obj, this.#area);
    }
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
  }
}
